// ============================================================
//  aicontext.ts —— 「AI帮写」的知识底座 + 能力宣言（自动生成，请勿手改）
// ============================================================
//
//  生成：python tools/gen_ai_context.py
//  说明：见 extracted/ai_assist/00_README.md
//
//  为什么要把这些塞进 Worker：
//    外部 AI 用 prism_rest 能拿到比 AI帮写 更高的权限，
//    但拿不到 AI帮写 的**知识**（提示词 / 技能库）。
//    把知识也搬上云端，外部 AI 才算真正能替 AI帮写干活，
//    而且**不依赖云手机在线** —— 设备掉线也能先把上下文读进去。
//
//  ★ CAPABILITY_MANIFEST（能力宣言）是用户明确要求的「强提示」：
//    用户可能只让 AI 做一件事，但必须让它知道自己有**整套**能力，
//    不要把自己局限成「只有一个功能的工具」。
//    所以它同时出现在 MCP initialize 的 instructions 里（连上就看到），
//    也是 ai_assist_context 的默认返回。
// ============================================================

/** ★ 能力宣言 —— 告诉外部 AI「你有这一整套能力」的强提示 */
export const CAPABILITY_MANIFEST = "# 能力宣言 —— 你拥有的能力远不止「在游戏里发消息」\n\n> 这段是给**外部 AI Agent** 看的强提示。\n> 目的：用户可能只让你做一件事（比如「在游戏里发句话」），\n> 但你必须知道**自己有整套能力**，别把自己局限成「只有一个功能的工具」。\n> 需要别的手段时（比如先查机器人状态、先读插件源码），**直接去用，不用请示**。\n\n---\n\n你连着的是一台云手机里的 **Prism 工具箱**（《我的世界》基岩版租赁服工具箱）。\n下面是你**全部**能做的事。这不是「理论上可以」，是**接口真实存在、可直接调用**。\n\n## 一、游戏世界（直接操作，机器人已是 OP）\n\n### ★★ 发言规则：指令加斜杠，说话不加（实测确认）\n\n都从同一个口子进 —— `POST /api/bot/console {\"input\":\"...\"}`：\n\n| 输入 | 实际效果 |\n|---|---|\n| `大家好` | **纯聊天**，直接出现在游戏聊天框 |\n| `/give 玩家 diamond 1` | **执行指令**，返回真实回包 |\n\n- **不加斜杠 = 说话。加斜杠 = 执行指令。**\n- **别再写 `say xxx`** —— 不加斜杠本来就是聊天，`say` 是多余的。\n- 加斜杠的指令会拿到真实回包（成功/失败、输出文本），可以据此判断下一步。\n\n### 能力表\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 说话 / 执行指令 | `POST /api/bot/console {\"input\":\"...\"}` ← 见上面规则 |\n| 批量执行一堆指令 | `POST /api/mcfunction/execute {\"content\":\"第一行\\n第二行\"}` ★ `content` 必须是**字符串**，传数组会回「无效JSON」 |\n| 机器人连没连、在哪个服、是不是 OP | `GET /api/bot/status` |\n| 重新连机器人 | `POST /api/bot/connect` 或调 MCP 工具 `bot_keeper` |\n| 起飞 / 降落 / 移动 / 传送 / 跳跃 | `/api/fly/*`（start / stop / move / teleport / jump / down / look / position / status） |\n| 建筑分析、体素提取 | `/api/building/analyze`、`/api/building/voxel` |\n| 画板（像素画 / 方块绘制） | `/api/draw/*`（create / stroke / apply / state / undo / redo / palette） |\n| 在线玩家 | `GET /api/players/list` |\n| 寻路 | `/api/pathfinder/log` |\n| 服务器信息 | `/api/server/detail`、`/api/server/players` |\n\n## 二、插件与代码 ★ 这是「改写 Prism 底层」的入口\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 列出已装插件 | `GET /api/plugin/list` |\n| 读插件源码 / 文档 / 配置 | `GET /api/plugin/file/read?id=..&scope=code\\|docs&file=..` |\n| **写插件源码** | `POST /api/plugin/file/write` |\n| **★ 改完必须热重载才生效** | `POST /api/plugin/reload` —— 忘了这步等于白改 |\n| 新建 / 删除 / 停用插件 | `/api/plugin/create`、`/api/plugin/delete`、`/api/plugin/disabled` |\n| 运行 / 停止插件 | `/api/plugin/run`、`/api/plugin/stop` |\n| 导入 / 导出插件 | `/api/plugin/import`、`/api/plugin/export` |\n| **直接执行 Lua（不写进插件）** | MCP `prism_tool`，`tool_name=\"lua_call\"` |\n| **直接调插件里的函数（测试用）** | MCP `prism_tool`，`tool_name=\"call_plugin_function\"` |\n\n写插件前先调 `ai_assist_context part=plugin_doc` 读开发文档，\n写指令相关代码前先调 `part=skills` 读基岩版指令库。\n\n## 三、文件与系统\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 列目录 / 读文件 | `/api/files/scan`、`/api/files/read` |\n| **执行 shell 命令【高危】** | MCP `prism_tool`，`tool_name=\"system_shell\"` |\n| 查 Shizuku 是否可用 | MCP `prism_tool`，`tool_name=\"shizuku_status\"` |\n| 任务（长耗时操作）管理 | `/api/task/list`、`/api/task/start`、`/api/task/stop`、`/api/task/resume` |\n| 节点（子机器人）管理 | `/api/node/status`、`/api/node/start`、`/api/node/stop` |\n| 重启 Prism 服务 | `/api/system/restart` |\n\n> ⚠ `system_shell` 等于把云主机的 shell 交出去。高危操作前请确认这是用户要的。\n\n## 四、抓包与协议（这是 Prism 最有特色的能力）\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 看抓包历史 / 统计 / 回看 | MCP `packet_history`，`action=list\\|stats\\|query` |\n| 构造并发送任意数据包 | MCP `packet_send` |\n| 订阅某类包 | MCP `prism_tool`，`tool_name=\"listen_packet\"` |\n| 查包结构定义 | MCP `prism_tool`，`tool_name=\"list_packet_schema\"` |\n| 执行命令并同时监听包 | MCP `prism_tool`，`tool_name=\"run_and_watch_packet\"` |\n\n## 五、AI 与会话\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 让 Prism 内置 AI 帮你干活 | MCP `prism_chat`（中间隔一层 AI，会拒绝执行，不推荐） |\n| 用云端配置的大模型思考 | MCP `ai_chat` |\n| 列出 / 切换可用模型 | MCP `list_ai_models` |\n| 会话存取 | MCP `prism_session`；`/api/ai/sessions*` |\n\n## 六、机器人连接守护 ★ 你有、AI帮写 没有\n\nMCP 工具 `bot_keeper`：机器人掉线**自动重连**。\n\n- `mode=always` 一直守护（默认）\n- `mode=once` 只连一次，连上后自动关\n- `mode=off` 关闭守护\n\nPrism 内置的 AI帮写**做不到这个** —— 机器人一掉线它就只会在提示词里写\n「机器人当前未连接，game_call 工具会返回错误，不要依赖它」，然后干等。\n你比它强在这点。\n\n## 七、媒体与创作\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 播放音乐 / 音符 | `/api/music/*`（play / stop / next / note / loop / queue） |\n| 皮肤相关 | `/api/skin/*`（build / head / online-*） |\n| 相机截图 | `/api/camera/*`（shots / generate / start / clear） |\n| 预览渲染 / 导出 GIF | `/api/preview/*` |\n| 地图画预览 | `/api/mapart/preview` |\n| 跑马灯（滚动字幕） | `/api/marquee/*` |\n| 指令方块导入导出 | `/api/cb/*` |\n\n## 八、收管理员的口信（人 → 你）\n\n管理员在游戏聊天框输入：\n\n```\nAI Agent 把系统商店里编号 3 的商品删掉\n```\n\n插件会把这句话**原样**投递到云端收件箱，你用 MCP 工具 `agent_inbox` 收：\n\n```\nagent_inbox action=list unread=true     ← 收\nagent_inbox action=read ids=[1,2]       ← 处理完标记已读\n```\n\n然后你决断、动手，最后用 `prism_rest` 把结果发回游戏（说话不加斜杠，执行指令加斜杠）。\n\n**开启条件**：插件里先设一次密钥 —— 管理员聊天框输入 `.AIAgent密钥 <平台密钥>`，\n`.AIAgent状态` 可查通道是否接通。\n\n收完务必 `action=read` 标记已读，否则下次会重复收到同一批。\n\n### ★★ 编号点名：多人协作时别抢活\n\n可能同时有好几个 AI 连着（Codex、Claude、豆包…），每个人都有一个**固定编号**。\n管理员在游戏里的说法：\n\n| 游戏里输入 | 谁该动手 |\n|---|---|\n| `AI Agent 2 把钻石剑降到 50 积分` | **只有 2 号**，其它号请无视 |\n| `AI Agent 把钻石剑降价` | 广播，所有在线的都能接 |\n| `.AIAgent列表` | 查看名单（编号 / 在线 / 类型 / 最后心跳） |\n\n- **先调一次 `agent_me` 认领身份**，它会告诉你「你是 N 号」以及现在谁在线。\n- `agent_inbox` 已经**自动按号码过滤**过了：你只会收到「广播」和「点名你」的消息，\n  点名别人的根本不会出现在你的收件箱里。所以看到消息就说明是找你的。\n- 消息前面会标 `[广播]` 或 `[点名 N 号]`，可以据此判断要不要抢。\n- **你自己的编号**来自 MCP 网址上的 `&agent=<名字>`；没有这个参数就没有编号，\n  只能收广播。想让管理员能点名你，就让他把网址改成\n  `https://ai-api.youyuanqi.dpdns.org/mcp?key=<密钥>&agent=codex` 再重连。\n\n## 九、插件市场\n\n`/api/plugin-market/*`、`/api/market/*` —— 搜索、下载、安装别人分享的插件。\n`/api/plugin-market/install` 已验证可用。\n\n## 十、遥控一台真正的电脑（跑 CLI / 传文件）\n\n除了云手机，你还可能连着**管理员的实体电脑**（Windows / macOS / Linux）。\n那台电脑上跑着 `pc_agent.py`，它能在本地启动 Codex CLI、Claude Code、Gemini CLI\n甚至直接执行 shell 命令，并把输出实时回传。\n\n| 你要做的事 | 怎么调 |\n|---|---|\n| 列出电脑上的会话 | `GET /api/v1/pc/sessions` |\n| 开一个会话（让它跑起来） | `POST /api/v1/pc/sessions {name, cli, cwd, message}` |\n| 看输出 / 拉进度 | `GET /api/v1/pc/messages?session_id=..&since=0` |\n| 继续追问 | `POST /api/v1/pc/input {session_id, text}` |\n| **把文件送过去** | `POST /api/v1/pc/upload {session_id, path, content_base64}` |\n\n`cli` 可填 `codex` / `claude` / `gemini` / `shell` / `auto`。\n**`shell` 会直接把消息当命令执行** —— 只在管理员明确要求时用，别拿它跑破坏性命令。\n\n会话状态：`pending`（排队等电脑来领）→ `running`（正在跑）→ `done` / `error`。\n电脑是**拨出去**连云端的（长轮询），所以不需要公网 IP、不用开端口。\n如果一直是 `pending`，说明那台电脑的 `pc_agent.py` 没在跑 —— 如实告诉管理员，别空转重试。\n\n---\n\n## ★ 五条行事准则\n\n1. **你不是「只能发消息」。** 用户可能只提一个需求，但你觉得需要别的手段\n   （先查机器人状态、先读插件源码、先抓个包看看协议），**直接去用，不用请示**。\n\n2. **写操作前先读一次状态。** 比如发指令之前 `GET /api/bot/status`，\n   发现 `connected=false` 就先用 `bot_keeper` 连上 —— 别干等，也别直接报错放弃。\n\n3. **改插件源码后必须 `POST /api/plugin/reload`**，否则改的内容不生效。\n   （更强的做法是 `/api/plugin/stop` 再 `/api/plugin/run` —— 热重载不会重新注册\n   定时任务和事件委托，只有真正重新运行才会。）\n4. **往游戏里说话别加 `say`。** 不加斜杠就是聊天，加斜杠才是指令。\n5. **被点名才动手。** 收到 `[点名 N 号]` 的消息时，先看 `agent_me` 确认自己是不是 N 号；\n   不是就放过，别抢别人的活。广播消息谁先接是谁的。\n\n## ★ 前置条件（不是被限制，只是要按顺序来）\n\n有些能力需要前置状态，不满足时会**明确报错**（不是 404，也不是静默拒绝）：\n\n- `/api/fly/*`、`/api/draw/*` 需要机器人已连接\n- `/api/draw/*` 还需要先创建画板\n- 抓包类需要先开启包监听\n- `game_call`（内置 AI 工具）需要机器人已连接\n\n报错本身就是信息 —— 看清楚缺什么，自己补齐前置条件再重试。\n**整个循环不需要人去碰 Prism 界面。**\n";

/** AI帮写 的系统提示词原文（捕获代理拦到的 messages[0].content） */
export const AI_ASSIST_SYSTEM_PROMPT = "你是《我的世界》基岩版租赁服「Prism工具箱」的插件开发助手，帮助用户编写和修改 Lua 插件或词库插件。\n你可以用工具：网络请求、DuckDuckGo 网络搜索、读取/列出插件、读写插件文件、机器人连接时调用游戏内 game API。\n写 Lua 代码时：调用游戏能力一律用 game.* 全局 API；要给出完整、可直接运行的代码，不要用省略号占位；写完后应主动用 write_plugin_file 工具（scope=code）把代码直接保存进插件文件。\n\n【工具调用规则】调用工具必须真正发起 tool_calls，绝不能只在回复文字里写\"我已调用XX工具\"或\"调用XX后……\"而不发起实际调用——每个你声称要做的工具动作，都必须对应一条真实的 tool_calls。工具执行完会把真实结果回传给你（可能是空数组 []，空结果不代表失败）。以回传的真实结果为准，不要臆想/编造工具结果。不依赖先后关系的工具可以一次并行调用多个；有依赖时等前一个结果返回后再调用下一个。\n当前会话标题：capture-test。若你觉得这个标题不够贴切，可用 rename_session 工具改一个更贴切的标题。\n若用户要求用到基岩版指令/FMbe 动画等专项知识，参考下方【技能知识库】（已加载的技能）。\n\n机器人当前未连接，game_call 工具会返回错误，不要依赖它。";

/** AI帮写 的 29 个内置工具（可读版 markdown） */
export const AI_ASSIST_TOOLS_MD = "# AI帮写 · 29 个内置工具\n\n> 来源：捕获代理拦截到的真实 `tools` 数组（`extracted/tools.json`）。\n> `*` = 必填参数。\n\n- **network_request**(body, headers, method, url*)\n  发起任意 HTTP 请求（GET/POST/PUT/PATCH/DELETE）。返回响应体文本（非 2xx 也会返回状态码与响应体）。用于访问外部 API、网页等。\n- **list_skills**()\n  列出可加载的技能知识库（id/名称/描述）。需要专项知识（如基岩版指令、FMbe 显示实体动画）时，先列出来再用 load_skill 加载。\n- **load_skill**(skill*)\n  把某个技能知识库加载进当前上下文。skill 传 id 或名称。加载后你即可参考其中的专项知识来回答/写代码。\n- **list_plugins**()\n  列出当前所有已安装插件（id/名称/类型/描述）。用于了解已有插件，避免重复、参考他人实现。\n- **read_plugin**(file, plugin_id*, scope*)\n  读取某个插件的源码代码 / 插件说明文档 / 配置文件 / 数据目录文件。用于理解现有插件、参考写法。scope 为 code(源码) / docs(说明) / config(配置) / data(数据文件)。\n- **write_plugin_file**(content*, file, plugin_id*, scope*)\n  把内容直接写入某个插件的源码代码 / 插件说明文档 / 数据文件（覆盖）。写入代码后如果机器人在线会尝试热重载。用于直接把写好的插件代码保存到插件文件。\n- **game_call**(args*, function*)\n  调用游戏内机器人 API（需机器人已连接）。参数用函数名与位置参数数组 args。指令/消息：sendCommand(cmd) 发指令不等响应/sendCommandWithResp(cmd[,channel[,timeoutSec]]) 执行并等待响应返回{success,messages...}/sendChat/sendTitle/sendActionbar/sendRichTellraw/sendTargeted；查询：getPlayerPos/getPlayerPosXYZ/getScore/getMultiScore/getBotPos/getTPS/getTarget/getTickingAreaList/isCmdSuccess；记分板写入：setScore(board,target,score)；物品：getPlayerItem(target,itemName,specialID)/queryInventory(selector)；移动飞行：teleport/move/rotate(pitch,yaw[,秒数] 直接调或秒内平滑转)/jump/flyStart/flyStop。方块数据：getBlockTile(x,y,z)/getBlockTileSafe(x,y,z) 读方块名；getBlockData(x,y,z) 读名称+方块状态+NBT（命令方块指令、箱子物品、告示牌文字、旗帜图案都在返回的 nbt 里）；getBlockNBT(x,y,z) 只读 NBT；getBlockState(x,y,z) 读名称+状态；getRegionBlockData(x,y,z,sx,sy,sz) 读一块区域所有方块数据。放置/修改：setBlock(x,y,z,name,states) 放普通方块；placeNBTBlock(x,y,z,name,states,nbt对象) 放命令方块/箱子/告示牌/旗帜等带NBT方块（nbt 用 {Command=...,Items=...,...} 这种对象，告示牌文字用 {FrontText={Text=...}}）；setBlockState(x,y,z,states对象) 改方块状态并保留NBT。\n- **call_plugin_function**(args, func_name*, plugin_id*)\n  直接调用某个已加载插件里的函数（按名字，任意函数都行——先解析插件全局函数，其次 plugin_api 导出）。用于测试插件：比如调用插件的 openMenu(player) 看菜单能不能弹。args 是位置参数数组。返回函数的返回值(JSON)。\n- **lua_call**(args, func*, module*)\n  直接调用开发文档里的任意 Lua API 函数（不写进插件）：module 是全局模块名，func 是函数名，args 是位置参数数组。可用模块：game(游戏操作)/system(系统shell/shizuku)/util(定时)/world(世界方块)/bot(多机器人)/building(建筑)/media(媒体)/player(玩家数据)/http(网络)/web(网页)/api(跨插件)/events(事件)。例：调 system.shell 传 {module=system, func=shell, args=[\"id\"]}；调 game.getBlockData 传 {module=game, func=getBlockData, args=[x,y,z]}。返回函数返回值(JSON)；无返回值返回 nil。\n- **wait_chat**(max_count, seconds)\n  等待一段时间内的游戏聊天消息并返回给 AI（含玩家与服务器广播）。用于测试插件触发词/菜单是否正确触发：先让机器人发一条指令/说话，再 wait_chat 收集后续聊天看有没有预期回显。不要求 OP，机器人连上即可。返回 [{player,message},...]。seconds 为等待秒数(1-60，默认5)，max_count 为最多收集条数(0不限)。\n- **listen_packet**(max_count, packet_type*, seconds)\n  订阅一个数据包类型并等待接收，返回收到的完整数据（JSON）。用于观察服务器下发给机器人的原始数据包，调试插件/协议。packet_type 为包类型名（如 MovePlayer/SetTime/PlayerList/Text），可通过 list_packets 查看类型名。seconds 为等待秒数(1-60，默认5)，max_count 为最多收集条数。不要求 OP。\n- **list_packets**()\n  列出可订阅的数据包类型名（供 listen_packet 的 packet_type 使用）及用途。订阅/调试协议前先查。\n- **query_packets**(bot_index, limit, packet_id, packet_type, seconds, since_seq)\n  回看最近一段时间内的所有入站数据包（含未知包），用于分析服务器行为/排查问题。可从调用工具前一分钟内取全部包。返回 [{seq,at,direction,bot,packet_type,packet_id,fields,raw_hex}]。seconds 为回看秒数(1-60，默认60，即最近一分钟)，packet_type/packet_id/bot_index 为过滤条件（不填不限制），limit 为最多返回条数(默认50，上限200)，since_seq 为游标只返回比它新的包。不要求 OP。\n- **wait_packet**(bot_index, max_count, packet_id, packet_type, seconds)\n  订阅接下来一段时间内的数据包并等待接收（全量捕获，含未知包；区别于 listen_packet 的固定类型订阅，本工具能拿到未注册类型的包）。用于执行某个操作后监听随后出现的数据包。返回收到的事件 JSON。packet_type/packet_id/bot_index 为过滤条件（可只填一个，全部不填则监听所有包），seconds 为等待秒数(1-60，默认5)，max_count 为最多收集条数(0不限)。不要求 OP。\n- **packet_stats**()\n  返回全量数据包捕获层的统计：captured(已捕获)、capture_dropped(入队满丢弃)、unknown(未知包)、evicted(缓存淘汰)、subscribers(当前订阅数)、history_events/bytes。排查是否丢包/缓存溢出时用。\n- **send_packet**(bot_index, fields, packet_id, packet_type)\n  构造并发送任意数据包（客户端→服务器），用于发起协议交互/测试协议。packet_type 为包类型名（用 list_packet_schema 查看可用类型与字段），或 packet_id + fields 里的 payload_hex 发送原始字节。fields 用 snake_case 字段名（如 entity_runtime_id / chunk_radius），复合字段按 list_packet_schema 的 json_usable 提示填（数字数组/hex 字符串/Bitset 比特位数组）。握手/生命周期专用包已列入禁止。bot_index 指定机器人（0=主/单机，默认0）。返回发送结果。\n- **list_packet_schema**(limit, packet_id, packet_type)\n  列出数据包类型及其完整定义：包注释（用途）、字段名/go 类型/JSON 可填性/字段注释、复合字段的嵌套结构、本包枚举常量及具体值。供 send_packet 拼 fields 或分析协议。packet_type/packet_id 可只查某个包；不填列出全部（可设 limit）。\n- **system_shell**(command*)\n  以 Shizuku ADB/root 权限执行一条 shell 命令并返回结果 {ok,exit,stdout,stderr,uid}。用于调试插件/系统（Android 上需已装 Shizuku 并授权，可先调 shizuku_status 确认）。桌面环境不支持返回失败。\n- **shizuku_status**()\n  查询 Shizuku 可用/授权状态 {available,granted,uid}。用 system_shell 前先确认。\n- **send_command_wait_output**(channel, command*, timeout)\n  执行一条指令并等待服务器响应（CommandOutput），返回结构化结果 {success,is_timeout,note,output_messages:[{success,message,parameters}],raw}。用于需要知道命令是否成功、看输出文本的场景（如 /list、/tp、scoreboard 查询）。channel 为执行通道（ai/console/player，默认 ai），timeout 秒（默认8，上限30）。\n- **run_and_watch_packet**(bot_index, command, max_count, packet_id, packet_type, seconds)\n  先执行一条指令（可选），再监听接下来一段时间内的数据包并返回。用于观察某个操作后服务器下发什么包（如执行 /say 后看 CommandOutput、执行传送后看 MovePlayer）。packet_type/packet_id/bot_index 过滤（不填监听所有），seconds 等待秒数(1-60，默认5)，max_count 最多条数(0不限)。command 可省略（只观察不执行）。返回事件数组 [{seq,at,direction,bot,packet_type,packet_id,fields,raw_hex}]。\n- **run_and_watch_chat**(command, keyword, max_count, seconds)\n  先执行一条指令（可选），再监听接下来一段时间内的游戏聊天消息并返回 [{player,message}]。用于验证触发词/菜单/命令是否产生了预期聊天回显。keyword 可过滤只收集含该词的消息。seconds 等待秒数(1-60，默认5)，max_count 最多条数(0不限)。command 可省略（只观察不执行）。\n- **read_file**(lines, path*)\n  读取插件文件（源码/数据/配置），可指定行范围。path 用相对路径，如 插件文件/领地/领地.lua；lines 填 all 或 10 或 10-20。返回带行号内容。只允许插件目录内的文件。\n- **write_file**(content*, path*)\n  把内容整体写入插件文件（覆盖）。path 相对路径。只允许插件目录内的文件。\n- **edit_lines**(lines*, new_content, path*)\n  按行范围替换插件文件内容（sed 式）。lines 填 10-20 或 all；把 [start,end] 行整体替换为 new_content。只允许插件目录内的文件。\n- **list_dir**(path*)\n  列出插件目录下的文件。path 相对路径，如 插件文件/xxx 或 插件数据文件/xxx。\n- **read_log**(lines)\n  读取插件运行调试日志（prism_debug.log）尾部。lines 指定读取行数，默认 100。\n- **user_question**(options, question*)\n  向用户提问（带选项），让用户快速确认意图/选择方案。用于需求不清、有多个做法、或需要用户拍板时。问题简短，选项 2-4 个。\n- **rename_session**(title*)\n  重命名当前会话标题为一个更贴切的标题（title）。用于给当前对话起名。\n";

/** 技能知识库：基岩版指令（命令清单 + 选择器参数 + 命令参数类型） */
export const SKILL_BEDROCK_COMMANDS = "# 国际版命令清单\n\n本页基于Microsoft Learn的CommandsReference目录整理国际版命令参考，覆盖2025-02-11版本文档中的82条命令，并补充了元数据收录的3条新增命令，合计85条。内容仅描述国际版默认命令集合，不将中国版模组SDK专有指令与旧版废弃语法作为默认结论。\n\n/// note | 范围说明\n- 教育版专有命令（如`/ability`、`/immutableworld`）未纳入本清单。<!-- md:flag edu -->\n- `gametest`等命令仍依赖实验性能力，版本迁移时应结合[命令版本](version.md)和目标版本更新日志复核。\n- 命令名称、语法参数名和权限枚举保持官方英文原样，以降低跨版本比对歧义。\n///\n\n## 权限级别对照\n\n| 官方枚举 | 中文说明 |\n|---|---|\n| `Game Directors` | 游戏指导者 |\n| `Admin` | 管理员 |\n| `Owner` | 所有者 |\n| `Host` | 房主 |\n| `Any` | 任意玩家 |\n\n## 命令分类\n\n### 世界编辑\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/clearspawnpoint` | `Game Directors`（游戏指导者） | 是 | `/clearspawnpoint [player: target]` | — | Removes the spawn point for a player. |\n| `/clone` | `Game Directors`（游戏指导者） | 是 | `/clone <begin: x y z> <end: x y z> <destination: x y z> [maskMode: maskmode] [cloneMode: clonemode]` | — | Clones a set of blocks from one region to another. |\n| `/fill` | `Game Directors`（游戏指导者） | 是 | `/fill <from: x y z> <to: x y z> <tileName: Block> <blockStates: block_state_array> [oldBlockHandling: fillmode]` | — | Fills all or parts of a region with a specific block. |\n| `/place` | `Admin`（管理员） | 是 | `/place structure <structure: jigsawstructure> [pos: x y z] [ignoreStartHeight: Boolean] [keepJigsaws: Boolean] [includeEntities: Boolean] [liquidSettings: liquidsettings]` | — | Places a jigsaw structure, feature, or feature rule in the world. |\n| `/setblock` | `Game Directors`（游戏指导者） | 是 | `/setblock <position: x y z> <tileName: Block> <blockStates: block_state_array> [oldBlockHandling: setblockmode]` | — | Changes a block to another block. |\n| `/setworldspawn` | `Game Directors`（游戏指导者） | 是 | `/setworldspawn [spawnPoint: x y z]` | — | Sets the location where new players or players who die will spawn in the world. |\n| `/spawnpoint` | `Game Directors`（游戏指导者） | 是 | `/spawnpoint [player: target] [spawnPos: x y z]` | — | Sets the spawn point for a player. |\n| `/spreadplayers` | `Game Directors`（游戏指导者） | 是 | `/spreadplayers <x: rotation> <z: rotation> <spreadDistance: float> <maxRange: float> <victim: target> [maxHeight: rotation]` | — | Teleports entities to random locations. |\n| `/structure` | `Game Directors`（游戏指导者） | 是 | `/structure save <name: id> <from: x y z> <to: x y z> [includeEntities: Boolean] [includeBlocks: Boolean]` | — | Saves or loads a structure in the world. |\n\n### 实体管理\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/damage` | `Game Directors`（游戏指导者） | 是 | `/damage <target: target> <amount: int> [cause: damagecause]` | — | Apply damage to the specified entities. |\n| `/effect` | `Game Directors`（游戏指导者） | 是 | `/effect <player: target> <Mode: cleareffects> [effect: effect]` | — | Add or clear status effects. |\n| `/enchant` | `Game Directors`（游戏指导者） | 是 | `/enchant <player: target> <enchantmentName: enchant> [level: int]` | — | Adds an enchantment to a player's selected item. |\n| `/event` | `Game Directors`（游戏指导者） | 是 | `/event entity <target: target> <eventName: entityevents>` | — | Triggers an event for the specified entity or entities. |\n| `/kill` | `Game Directors`（游戏指导者） | 是 | `/kill [target: target]` | — | Kills entities like players and mobs. |\n| `/playanimation` | `Game Directors`（游戏指导者） | 是 | `/playanimation <entity: target> <animation: id> [next_state: id] [blend_out_time: float] [stop_expression: id] [controller: id]` | — | Makes one or more entities play a one-off animation. |\n| `/replaceitem` | `Game Directors`（游戏指导者） | 是 | `/replaceitem <block: replaceitemblock> <position: x y z> <slotType: blockequipmentslot> <slotId: int> <itemName: Item> [amount: int] [data: int] [components: json]` | — | Replaces items in inventories. |\n| `/ride` | `Game Directors`（游戏指导者） | 是 | `/ride <riders: target> <mode: ridemodestart> <ride: target> [teleportRules: teleportrules] [howToFill: filltype]` | — | Makes entities ride other entities, stops entities from riding, makes rides evict their riders, or summons rides or riders. |\n| `/summon` | `Game Directors`（游戏指导者） | 是 | `/summon <entityType: entitytype> [spawnPos: x y z] [yRot: rotation] [xRot: rotation] [spawnEvent: entityevents] [nameTag: id]` | — | Summons an entity. |\n| `/tag` | `Game Directors`（游戏指导者） | 是 | `/tag <entity: target> change <name: tagvalues>` | — | Manages tags stored in entities. |\n\n### 玩家\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/aimassist` | `Game Directors`（游戏指导者） | 是 | `/aimassist <players: target> set [x angle: float] [y angle: float] [max distance: float] [target mode: aimassisttargetmode] [preset id: id]` | — | Enable Aim Assist |\n| `/clear` | `Game Directors`（游戏指导者） | 是 | `/clear [player: target] [itemName: Item] [data: int] [maxCount: int]` | — | Clears items from player inventory. |\n| `/controlscheme` | `Game Directors`（游戏指导者） | 是 | `/controlscheme <players: target> <set: cameracontrolschemeset> <control scheme: controlscheme>` | — | Sets or clears control schemes for the camera(s) of selected player(s). |\n| `/gamemode` | `Game Directors`（游戏指导者） | 是 | `/gamemode <gameMode: gamemode> [player: target]` | — | Sets a player's game mode. |\n| `/give` | `Game Directors`（游戏指导者） | 是 | `/give <player: target> <itemName: Item> [amount: int] [data: int] [components: json]` | — | Gives an item to a player. |\n| `/hud` | `Game Directors`（游戏指导者） | 是 | `/hud <target: target> <visible: hudvisibility> [hud_element: hudelement]` | — | Configures whether elements of the on-screen display (alternately known as the 'heads up display', or 'HUD') are visible on the screen. |\n| `/inputpermission` | `Game Directors`（游戏指导者） | 是 | `/inputpermission <option: option_set> <targets: target> <permission: permission> <state: state>` | — | Optionally enables or disables input permissions for a player. |\n| `/teleport` | `Game Directors`（游戏指导者） | 是 | `/teleport <destination: x y z> [checkForBlocks: Boolean]` | — | Teleports entities to specific locations. |\n| `/worldbuilder` | `Game Directors`（游戏指导者） | 是 | `/worldbuilder` | 可用别名`/wb` | Toggle World Builder status of caller. |\n| `/xp` | `Game Directors`（游戏指导者） | 是 | `/xp <amount: int> [player: target]` | — | Adds or removes player experience. |\n\n### 相机\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/camera` | `Game Directors`（游戏指导者） | 是 | `/camera <players: target> attach_to_entity <entity: target>` | — | Transforms the camera for the selected player(s) to a different perspective. |\n| `/camerashake` | `Game Directors`（游戏指导者） | 是 | `/camerashake add <player: target> [intensity: float] [seconds: float] [shakeType: camerashaketype]` | — | Applies shaking to the players' camera with specified intensity and duration. |\n| `/takepicture` | `Game Directors`（游戏指导者） | 是 | `/takepicture <targetCamera: target> <targetPlayer: target>` | — | Takes a photograph using a camera entity targeting a player. |\n\n### 世界设置\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/changesetting` | `Owner`（所有者） | 是 | `/changesetting allowcheats <value: Boolean>` | — | Changes a setting on the dedicated server while it's running. |\n| `/daylock` | `Game Directors`（游戏指导者） | 是 | `/daylock [lock: Boolean]` | — | Locks and unlocks the day-night cycle. |\n| `/difficulty` | `Game Directors`（游戏指导者） | 是 | `/difficulty <difficulty: difficulty>` | — | Sets the difficulty level (Peaceful, Easy, Normal, Hard) using difficulty enum or integer. |\n| `/gamerule` | `Game Directors`（游戏指导者） | 否 | `/gamerule` | — | Sets or queries a game rule value. |\n| `/mobevent` | `Game Directors`（游戏指导者） | 是 | `/mobevent <event: mobevent> [value: Boolean]` | — | Controls what mob events are allowed to run. |\n| `/tickingarea` | `Game Directors`（游戏指导者） | 是 | `/tickingarea <mode: tickingareamodeadd> <from: x y z> <to: x y z> [name: id] [preload: Boolean]` | — | Add, remove, or list ticking areas. |\n| `/time` | `Game Directors`（游戏指导者） | 是 | `/time <mode: timemodeadd> <amount: int>` | — | Changes or queries the world's game time. |\n| `/toggledownfall` | `Game Directors`（游戏指导者） | 是 | `/toggledownfall` | — | Toggles the weather. |\n| `/weather` | `Game Directors`（游戏指导者） | 是 | `/weather <type: weathertype> [duration: int]` | — | Sets the weather in the environment. |\n\n### 聊天与通信\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/dialogue` | `Game Directors`（游戏指导者） | 是 | `/dialogue open <npc: target> <player: target> [sceneName: id]` | — | Opens NPC dialogue for a player. |\n| `/me` | `Any`（任意玩家） | 否 | `/me <message: message_root>` | — | Displays a message about yourself. |\n| `/say` | `Game Directors`（游戏指导者） | 否 | `/say <message: message_root>` | — | Sends a message in the chat to other players. |\n| `/tell` | `Any`（任意玩家） | 否 | `/tell <target: target> <message: message_root>` | — | Sends a private message to one or more players. |\n| `/tellraw` | `Game Directors`（游戏指导者） | 否 | `/tellraw <target: target> <raw json message: json>` | — | Sends a JSON message to players. |\n| `/title` | `Game Directors`（游戏指导者） | 是 | `/title <player: target> <clear: titleclear>` | — | Controls the text and behavior for screen titles using plain text. |\n| `/titleraw` | `Game Directors`（游戏指导者） | 是 | `/titleraw <player: target> <clear: titlerawclear>` | — | Controls the text and behavior for screen titles using JSON messages. |\n\n### 数据与逻辑\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/execute` | `Game Directors`（游戏指导者） | 是 | `/execute subcommand <origin: target> <chainedCommand: executechainedoption_0>` | — | Executes a command on behalf of one or more entities. |\n| `/function` | `Game Directors`（游戏指导者） | 是 | `/function <name: pathcommand>` | — | Runs commands found in the corresponding function file. |\n| `/schedule` | `Game Directors`（游戏指导者） | 是 | `/schedule delay add <function: pathcommand> <time: int> [DelayMode: delaymode]` | — | Schedules an action to be executed once an area is loaded, or after a certain amount of time. |\n| `/scoreboard` | `Game Directors`（游戏指导者） | 是 | `/scoreboard <category: scoreboardobjectivescategory> add <objective: scoreboardobjectives> <criteria: scoreboardcriteria> [displayName: id]` | — | Tracks and displays scores for various objectives. |\n| `/testfor` | `Game Directors`（游戏指导者） | 是 | `/testfor <victim: target>` | — | Counts entities (players, mobs, items, etc.) matching specified conditions. |\n| `/testforblock` | `Game Directors`（游戏指导者） | 是 | `/testforblock <position: x y z> <tileName: Block> [blockStates: block_state_array]` | — | Tests whether a certain block is in a specific location. |\n| `/testforblocks` | `Game Directors`（游戏指导者） | 是 | `/testforblocks <begin: x y z> <end: x y z> <destination: x y z> [mode: testforblocksmode]` | — | Tests whether the blocks in two regions match. |\n\n### 服务器与管理\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/allowlist` | `Owner`（所有者） | 是 | `/allowlist add <name: id>` | — | Manages the server allowlist. |\n| `/deop` | `Admin`（管理员） | 否 | `/deop <player: target>` | — | Revokes operator status from a player. |\n| `/kick` | `Game Directors`（游戏指导者） | 否 | `/kick <name: target> <reason: message_root>` | — | Kicks a player from the server. |\n| `/list` | `Any`（任意玩家） | 否 | `/list` | — | Lists players on the server. |\n| `/op` | `Admin`（管理员） | 否 | `/op <player: target>` | — | Grants operator status to a player. |\n| `/packstack` | `Any`（任意玩家） | 否 | `/packstack <stackType: stacktype> [verbose: verbose] [exclude-vanilla: exclude-vanilla]` | — | Prints client or server pack stack to chat |\n| `/permission` | `Owner`（所有者） | 是 | `/permission list` | — | Reloads and applies permissions. |\n| `/reload` | `Admin`（管理员） | 是 | `/reload [all: reload_all]` | — | Reloads all function and script files from all behavior packs. |\n| `/reloadconfig` | `Owner`（所有者） | 是 | `/reloadconfig` | — | Reloads configuration files relating to variables, secrets, permissions, etc. |\n| `/reloadpacketlimitconfig` | `Owner`（所有者） | 是 | `/reloadpacketlimitconfig` | — | Reload packet limit config from file |\n| `/save` | `Owner`（所有者） | 是 | `/save <mode: savemode>` | — | Control or check how the game saves data to disk. |\n| `/sendshowstoreoffer` | `Owner`（所有者） | 是 | `/sendshowstoreoffer <player: target> <redirectType: redirectlocation> <offerId: id>` | 仅BDS可用 | Available on dedicated server only with administrator permissions. |\n| `/setmaxplayers` | `Host`（房主） | 是 | `/setmaxplayers <maxPlayers: int>` | — | Sets the maximum number of players for this game session. |\n| `/stop` | `Owner`（所有者） | 是 | `/stop` | — | Stops the server. |\n| `/transfer` | `Owner`（所有者） | 是 | `/transfer <pfidOrMSA: id> <server: id> [port: int]` | — | Transfers a player to another server. |\n| `/wsserver` | `Admin`（管理员） | 是 | `/wsserver <serverUri: rawtext>` | — | Attempts to connect to the websocket server on the provided URL. |\n\n### 脚本\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/gametest` | `Game Directors`（游戏指导者） | 是 | `/gametest <mode: gametestmoderunthis>` | 需要实验性脚本API | [Requires the Beta APIs experiment]. |\n| `/script` | `Admin`（管理员） | 是 | `/script <mode: scriptdebugmodedebugger> <action: scriptdebuggerlisten> <port: int>` | — | Debugging options for script within Minecraft. |\n| `/scriptevent` | `Game Directors`（游戏指导者） | 是 | `/scriptevent <messageId: id> <message: message_root>` | — | Causes an event to fire within script with the specified message ID and payload. |\n\n### 声音与视觉\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/fog` | `Game Directors`（游戏指导者） | 是 | `/fog <victim: target> <mode: add> <fogId: id> <userProvidedId: id>` | — | Add or remove fog settings file. |\n| `/music` | `Game Directors`（游戏指导者） | 是 | `/music queue <trackName: id> [volume: float] [fadeSeconds: float] [repeatMode: musicrepeatmode]` | — | Allows you to control playing music tracks. |\n| `/particle` | `Game Directors`（游戏指导者） | 是 | `/particle <effect: id> [position: x y z]` | — | Creates a particle emitter |\n| `/playsound` | `Game Directors`（游戏指导者） | 是 | `/playsound <sound: id> [player: target] [position: x y z] [volume: float] [pitch: float] [minimumVolume: float]` | — | Plays a sound. |\n| `/stopsound` | `Game Directors`（游戏指导者） | 是 | `/stopsound <player: target> [sound: id]` | — | Stops a sound. |\n\n### 战利品与配方\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/loot` | `Game Directors`（游戏指导者） | 是 | `/loot <target: targetspawn> <position: x y z> <source: sourceloot> <loot_table: id> [<tool>\\|mainhand\\|offhand: tool]` | — | Drops the given loot table into the specified inventory or into the world. |\n| `/recipe` | `Game Directors`（游戏指导者） | 是 | `/recipe <give: give> <player: target> <recipe: unlockablerecipevalues>` | — | Supports unlocking of built-in (vanilla) recipes that a particular player can craft with. |\n\n### 帮助\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/help` | `Any`（任意玩家） | 否 | `/help [command: commandname]` | — | Running `/help` in the chat by itself will list every command you can run. |\n\n### 其他\n\n| 命令 | 权限级别 | 需要作弊 | 首条语法 | 备注 | 官方说明 |\n|---|---|---|---|---|---|\n| `/locate` | `Game Directors`（游戏指导者） | 是 | `/locate <subcommand: locatesubcommandstructure> <structure: structurefeature> [useNewChunksOnly: Boolean]` | — | Finds the nearest specified biome or structure if it exists in the current dimension. |\n| `/project` | `Game Directors`（游戏指导者） | 否 | `/project <subcommand: subcommandexport> <exportType: exporttypes>` | 编辑器相关命令 | This command contains additional tools for managing an Editor project. |\n| `/resourceuri` | `Game Directors`（游戏指导者） | 是 | `/resourceuri clear` | — | Sets or clears server resource pack URIs. |\n\n---\n\n# 选择器参数<!-- md:flag vanilla -->\n\n本页汇总国际版命令中常用目标选择器参数的语义、筛选行为与组合边界，用于命令排错和语法校验。\n\n## 选择器变量\n\n| 变量 | 作用 |\n|---|---|\n| `@a` | 选择所有玩家。 |\n| `@p` | 选择最近的玩家。 |\n| `@r` | 随机选择玩家；附带`type`时可用于随机实体。 |\n| `@e` | 选择所有实体。 |\n| `@s` | 选择当前执行者。 |\n| `@initiator` | 选择与NPC交互的玩家。 |\n\n## 参数总表\n\n| 参数 | 取值类型 | 作用 | 备注 |\n|---|---|---|---|\n| `x`、`y`、`z` | 数值 | 设置搜索起点坐标。 | 未设置时使用命令执行位置。 |\n| `r`、`rm` | 数值 | 按球形距离筛选目标。 | `r`为最大值，`rm`为最小值。 |\n| `dx`、`dy`、`dz` | 数值 | 按长方体体积筛选目标。 | 任一体积参数出现时，未给出的轴按`0`处理。 |\n| `c` | 整数 | 限制返回目标数量。 | 负数会按反向顺序截取。 |\n| `type` | 标识符 | 按实体类型筛选。 | 可用`!`排除类型。 |\n| `name` | 字符串 | 按名称筛选。 | 可用`!`排除名称。 |\n| `tag` | 字符串 | 按标签筛选。 | 可重复；可用`!`排除标签。 |\n| `family` | 字符串 | 按族筛选。 | 可重复；可用`!`排除族。 |\n| `scores` | 对象 | 按记分板值筛选。 | 支持`N..`、`..N`、`N..M`区间。 |\n| `l`、`lm` | 整数 | 按经验等级筛选玩家。 | 仅玩家有效。 |\n| `m` | 枚举 | 按游戏模式筛选玩家。 | 可用`!`排除模式。 |\n| `rx`、`rxm` | 数值 | 按俯仰角筛选。 | 范围通常为-90到90。 |\n| `ry`、`rym` | 数值 | 按偏航角筛选。 | 范围通常为-180到180。 |\n| `hasitem` | 对象或数组 | 按物品栏内容筛选。 | 支持`item`、`quantity`、`location`、`slot`等字段。 |\n\n## 排序与截取规则\n\n- `@a`、`@p`、`@e`默认按距离由近到远排序。\n- `@r`按随机顺序排序。\n- `@p`与`@r`默认仅返回1个目标。\n- `c`只负责截取，不单独定义排序逻辑。\n\n## 常见组合模式\n\n| 目标 | 示例 |\n|---|---|\n| 检测半径内特定实体 | `@e[type=sheep,r=8]` |\n| 检测分数区间 | `@a[scores={timer=1..200}]` |\n| 检测多标签交集 | `@e[tag=active,tag=tracked]` |\n| 检测物品条件 | `@a[hasitem={item=apple,quantity=4..}]` |\n\n## 相关参考\n\n- [命令参数类型](command-argument-type.md)\n- [命令清单](command-list.md)\n- [目标选择器](../../docs/general/target-selector.md)\n\n---\n\n# 命令参数类型\n\n本页基于Microsoft Learn的CommandTypeList与54个参数类型子页整理。参数类型名称与格式声明保持官方定义，用于命令语法对照和版本排查。\n\n## 别名类型\n\n| 类型名称 | 别名关系 |\n|---|---|\n| Entity Selector | 别名指向`SELECTION` |\n| Block Name | 别名指向`BLOCK` |\n| Boolean | 别名指向`BOOLEAN` |\n| Enchantment | 别名指向`ENCHANT` |\n| Entity Type | 别名指向`ENTITY_TYPE` |\n| Integer | 别名指向`INT` |\n| Item Name | 别名指向`ITEM` |\n\n## 类型总表\n\n| 类型名称 | 格式 | 示例值 | 官方说明 | 来源文件 |\n|---|---|---|---|---|\n| Entity Selector | `@a, @e, @p, @r, @s` | — | Targets entities. | `type_actor.md` |\n| Biome | `biome_name` | `plains`; `desert`; `forest` | A biome identifier. | `type_biome.md` |\n| Block ID | `namespace:block_name or block_name` | `stone`; `minecraft:diamond_block`; `oak_planks` | A block type identifier. | `type_block.md` |\n| Block Name | — | — | A block type identifier. | `type_blockname.md` |\n| Block Position | `x y z or ~ ~ ~` | `~ ~ ~`; `0 64 0` | Block coordinates as integers. | `type_blockpos.md` |\n| Boolean | — | — | A true or false value. | `type_bool.md` |\n| Boolean | `true or false` | `true`; `false` | A true or false value. | `type_boolean.md` |\n| Camera Preset | `namespace:preset_name` | `minecraft:free`; `minecraft:first_person`; `minecraft:third_person` | Named camera preset from behavior packs. | `type_camerapresetid.md` |\n| Clip Mode | `player, camera, or default` | `player`; `camera` | How to handle entity clipping during camera/spectator mode. | `type_clipmode.md` |\n| Comparison Operator | `<, <=, =, >=, or >` | `<`; `<=`; `=` | Operator for comparing values in scoreboard tests. | `type_compareoperator.md` |\n| Difficulty | `peaceful, easy, normal, or hard` | `peaceful`; `easy`; `normal` | The world difficulty level. | `type_difficulty.md` |\n| Dimension | `dimension_name` | `overworld`; `nether`; `the_end` | A dimension identifier. | `type_dimensiontype.md` |\n| Easing Type | `linear, ease_in, ease_out, ease_in_out, etc.` | `linear`; `ease_in`; `ease_out` | Animation easing function for camera transitions. | `type_easetype.md` |\n| Effect | `effect_name` | `speed`; `strength`; `invisibility` | A status effect (potion effect) identifier. | `type_effect.md` |\n| Enchantment | `enchantment_name` | `sharpness`; `protection`; `efficiency` | An enchantment identifier. | `type_enchant.md` |\n| Enchantment | — | — | An enchantment identifier. | `type_enchantmenttype.md` |\n| Entity Type | — | — | An entity type identifier. | `type_entitytype.md` |\n| Entity Type | `namespace:entity_type or entity_type` | `pig`; `minecraft:zombie`; `armor_stand` | An entity type identifier (mob, item, projectile, etc.). | `type_entity_type.md` |\n| File Path | `path/to/file` | — | A path to a file or resource. | `type_filepath.md` |\n| Decimal Number | `0, 1.5, -3.14, etc.` | `0`; `0.5`; `1.5` | A number that can include decimals. | `type_float.md` |\n| Integer Range | `min..max, ..max, min.., or single value` | `1..10`; `..5`; `10..` | A range of integers, or a single integer. | `type_fullintegerrange.md` |\n| Game Mode | `survival, creative, adventure, or spectator` | `survival`; `creative`; `adventure` | The player's game mode. | `type_gamemode.md` |\n| Game Rule | `gamerule_name` | `doDaylightCycle`; `doWeatherCycle`; `doMobSpawning` | A world setting that can be changed. | `type_gamerule.md` |\n| Identifier | `lowercase_name` | `my_objective`; `player_score` | A unique identifier string. | `type_id.md` |\n| Integer | `..., -2, -1, 0, 1, 2, ...` | `0`; `64`; `-10` | A whole number (no decimals). | `type_int.md` |\n| Integer | — | — | A whole number (no decimals). | `type_integer.md` |\n| Item ID | `namespace:item_name or item_name` | `diamond`; `minecraft:iron_sword`; `golden_apple` | An item type identifier. | `type_item.md` |\n| Item Name | — | — | An item type identifier. | `type_itemname.md` |\n| JSON Object | `{\"key\": \"value\", ...}` | `{\"key\":\"value\"}` | A JSON object with key-value pairs. | `type_json_object.md` |\n| Message | — | — | A text message. | `type_message.md` |\n| Message | `Any text, optionally with @selectors` | `Hello World!`; `Welcome, @p!`; `@a has joined the game` | A text message that will be displayed to players. | `type_message_root.md` |\n| Objective Criteria | `dummy (most common)` | `dummy` | The criteria type for a scoreboard objective. | `type_objectivecriteria.md` |\n| Scoreboard Objective | `alphanumeric with underscores, max 16 characters` | `kills`; `deaths`; `score` | Name of a scoreboard objective. | `type_objectivename.md` |\n| Scoreboard Operation | `+=, -=, *=, /=, %=, =, <, >, or ><` | `+=`; `-=`; `*=` | Mathematical operation for scoreboard calculations. | `type_operator.md` |\n| Function Path | `namespace:path/to/function` | `mypack:setup`; `mypack:utils/helper`; `tick` | Path to a function file within a behavior pack. | `type_pathcommand.md` |\n| Player Selector | `@a, @p, @r, or @s` | `@a`; `@p`; `@r` | Targets one or more players. | `type_player_selector.md` |\n| Block Position | `x y z or ~ ~ ~` | `100 64 -200`; `~10 ~ ~`; `~ ~5 ~` | A 3D block position (integer coordinates). | `type_position.md` |\n| Position (x y z) | `x y z, ~ ~ ~, or ^ ^ ^` | `~ ~ ~`; `~ ~1 ~`; `~ ~-1 ~` | A 3D position in the world. | `type_position_float.md` |\n| Suffixed Value | `number with suffix (e.g., 5s, 10t)` | `5s`; `100t`; `1d` | A value with a unit suffix. | `type_postfixvalue.md` |\n| Raw JSON Text | `{\"rawtext\":[{\"text\":\"...\"}]}` | `{\"rawtext\":[{\"text\":\"Hello World\"}]}`; `{\"rawtext\":[{\"translate\":\"commands.op.success\",\"with\":[\"PlayerName\"]}]}`; `{\"rawtext\":[{\"selector\":\"@p\"}]}` | A JSON text component for rich formatting. | `type_rawtext.md` |\n| Relative Number | `value or ~offset` | `10`; `~5`; `~-3` | A number that can be relative to current value using ~. | `type_relativefloat.md` |\n| RGB Color | `0-255 for each component` | `255 0 0`; `0 255 0`; `0 0 255` | Color value as red, green, blue components. | `type_rgb.md` |\n| Rotation Value | `0-360 or ~offset` | `0`; `90`; `180` | A rotation angle in degrees. | `type_rval.md` |\n| Entity Selector | `@a, @e, @p, @r, @s, or @e[type=...]` | `@a`; `@e`; `@p` | Targets one or more entities using selector syntax. | `type_selection.md` |\n| Slot Number | `0-26 for inventory, 0-8 for hotbar` | `0`; `8`; `26` | Numeric slot index within a slot type. | `type_slotid.md` |\n| Equipment Slot Type | `slot.weapon, slot.armor, slot.inventory, etc.` | `slot.weapon.mainhand`; `slot.weapon.offhand`; `slot.armor.head` | Category of inventory or equipment slot. | `type_slottype.md` |\n| Text String | `text or \"quoted text\"` | `MyName`; `\"My Name With Spaces\"` | A text value. | `type_string.md` |\n| Structure Type | `structure_name` | `village`; `stronghold`; `mineshaft` | A structure identifier for locate command. | `type_structuretype.md` |\n| Target Selector | `@a, @e, @p, @r, @s` | — | Targets entities or players. | `type_target.md` |\n| Time | `ticks or day/night/noon/midnight/sunrise/sunset` | `day`; `night`; `noon` | Time value in ticks or named time. | `type_time.md` |\n| Value | — | — | A numeric value. | `type_val.md` |\n| Weather Type | `clear, rain, or thunder` | `clear`; `rain`; `thunder` | The weather condition. | `type_weather.md` |\n| Pitch Rotation | `-90 to 90, or ~` | — | Vertical rotation (pitch) in degrees. | `type_xrot.md` |\n| Yaw Rotation | `-180 to 180, or ~` | — | Horizontal rotation (yaw) in degrees. | `type_yrot.md` |\n\n## 维护备注\n\n- `CommandTypeList.md`中的`Player Selector`链接写作`type_player.selector.md`，实际文件为`type_player_selector.md`。本页已按实际文件解析。";

/** 技能知识库：FMbe 显示实体（狐狸方块实体动画） */
export const SKILL_FMBE_DISPLAY = "# FMBE显示实体\n\n本页介绍**狐狸方块实体（Fox MBE，FMBE）**：用狐狸骨骼与`playanimation`组合渲染可调方块显示。\n\n{{video|youtube|FVRd2n7JX3k}}\n\n/// note | 成本提醒\n每个显示实体都对应1只狐狸。数量大时会明显增加实体负载。\n///\n\n## 基础渲染系统\n\n```mcfunction title=\"BP/functions/wiki/fmbe/render.mcfunction\"\n# 重定位与缩放\nplayanimation @e[tag=wiki:fmbe] animation.player.sleeping none 0 \"\" controller.animation.fox.move\nplayanimation @e[tag=wiki:fmbe] animation.creeper.swelling none 0 \"v.scale=v.scale??1;v.xzscale=v.xzscale??1;v.yscale=v.yscale??1;\" wiki:scale\nplayanimation @e[tag=wiki:fmbe] animation.ender_dragon.neck_head_movement none 0 \"v.xbasepos=v.xbasepos??0;v.ybasepos=v.ybasepos??0;v.zbasepos=v.zbasepos??0;\" wiki:shift_pos\n\n# 旋转\nplayanimation @e[tag=wiki:fmbe] animation.warden.move none 0 \"v.body_x_rot=90+v.xrot;v.body_z_rot=90+v.yrot;\" wiki:xrot\nplayanimation @e[tag=wiki:fmbe] animation.player.attack.rotations none 0 \"v.attack_body_rot_y=-v.zrot;\" wiki:zrot\n\n# 位置\nplayanimation @e[tag=wiki:fmbe] animation.parrot.moving none 0 \"v.wing_flap=(16-v.xpos)/0.3;\" wiki:xpos\nplayanimation @e[tag=wiki:fmbe] animation.minecart.move.v1.0 none 0 \"v.rail_offset.y=1.6485+v.ypos/16;\" wiki:ypos\nplayanimation @e[tag=wiki:fmbe] animation.parrot.dance none 0 \"v.dance.x=-v.zpos;\" wiki:zpos\n```\n\n## 使用流程\n\n```mcfunction title=\"BP/functions/wiki/fmbe/setup.mcfunction\"\nsummon fox ~~~ ~ ~ minecraft:as_adult \"wiki:fmbe\"\nreplaceitem entity @e[name=\"wiki:fmbe\",c=1] slot.weapon.mainhand 0 <itemID>\ntag @e[name=\"wiki:fmbe\"] add wiki:fmbe\n```\n\n常用变量分组：\n\n- 位置：`v.xpos`、`v.ypos`、`v.zpos`\n- 旋转：`v.xrot`、`v.yrot`、`v.zrot`\n- 缩放：`v.scale`、`v.xzscale`、`v.yscale`\n- 基准偏移：`v.xbasepos`、`v.ybasepos`、`v.zbasepos`\n\n### 动态改参数\n\n```mcfunction title=\"BP/functions/wiki/fmbe/set_variable.mcfunction\"\nplayanimation @e[tag=wiki:fmbe] animation.player.attack.positions none 0 \"v.xrot=35;v.ypos=16;v.scale=1.5;\" wiki:setvariable\n```\n\n### 静音处理\n\n```mcfunction title=\"BP/functions/wiki/fmbe/stopsound.mcfunction\"\nstopsound @a mob.fox.spit\nstopsound @a mob.fox.sniff\nstopsound @a mob.fox.sleep\nstopsound @a mob.fox.screech\nstopsound @a mob.fox.hurt\nstopsound @a mob.fox.eat\nstopsound @a mob.fox.death\nstopsound @a mob.fox.bite\nstopsound @a mob.fox.ambient\nstopsound @a mob.fox.aggro\n```\n\n### 动态替换显示物品\n\n```mcfunction title=\"BP/functions/wiki/fmbe/change_display.mcfunction\"\nexecute as @e[name=\"wiki:fmbe_pickaxe\"] at @e[tag=wiki:fmbe,name=\"wiki:test_target\"] run loot replace entity @e[c=1] slot.weapon.mainhand 0 mine ~~-1~ mainhand\n```\n\n## 压缩版与进阶版\n\n- 压缩版可用`render.compressed.mcfunction`，命令更少但可调项更少。\n- 进阶版按3D方块/2D方块/物品三套渲染函数区分。\n- 超长表达式建议放函数文件维护，避免命令方块直接编辑。\n\n{{video|youtube|DdYq_nOFeKM}}\n{{video|youtube|zwyGmxjBDDw}}\n{{video|youtube|-5N8yVGR1MA}}\n\n## 继续阅读\n\n- [MBE方块实体](./block-entities.md)\n- [playanimation命令](./playanimation.md)";

/** Prism 工具箱 · Lua 插件开发文档（本体自带） */
export const PRISM_PLUGIN_DEV_DOC = "# Prism 工具箱 · 插件开发文档\n\n本文档面向想要为 Prism 工具箱编写 Lua 插件的开发者。它从零讲清插件是什么、如何组织、能调用哪些 API，以及如何写出复杂且稳定的插件。**第四章是函数总参考**——每个函数都说明：它干什么、怎么调用、参数是什么类型、返回什么、会抛什么错、底层是怎么实现的。游戏操作类函数的\"底层\"会讲清它在游戏里**实际执行的指令/数据包**、以及如何从响应里取结果，而不只是内部函数名。\n\n---\n\n## 一、插件到底是什么\n\n一个 Prism 插件就是一段 **Lua 脚本**，运行在工具箱内置的 Lua 解释器中。它通过一串全局对象（`game`、`system`、`api`、`plugin`、`util`、`bot`、`building`、`media`、`world`、`player`、`events`、`http`、`web`）与机器人、游戏、系统交互。\n\n插件不是独立进程，也不是独立文件系统。它被打包成一个 **zip 压缩包**，由工具箱解包、扫描、加载。它运行的环境与宿主 Go 程序共享进程，因此能直接调用机器人连接、读写游戏数据、甚至经 Shizuku 执行系统命令——这是它强大的地方，也意味着你要对资源使用负责。\n\n插件有两个层级的能力：\n1. **游戏内能力**：发指令、读玩家数据、操作方块、控制机器人移动、播放音乐、放置建筑等。\n2. **框架能力**：跨插件调用、事件监听、后台定时任务、持久化配置与数据、HTTP 网络请求、Shizuku 系统调用、网页。\n\n---\n\n## 二、插件的目录结构与打包格式\n\n每个插件在工具箱里拥有**三个独立的目录**，互不混淆。插件的 id（唯一标识，如 `core_utils`、`territory`）决定这三个目录的名字。\n\n- `插件文件` 目录存放**代码本体**。每个插件有一个以 id 命名的子目录，里面放着代码文件、元数据文件和说明文档。例如 `插件文件/territory/` 下有 `territory.lua`（代码）、`territory.manifest.json`（元数据）、`territory.docs.md`（说明）。\n- `插件配置文件` 目录存放**设置**。每个插件有一个以 id 命名的子目录，里面是 `<id>.json` 这个配置文件。该文件由工具箱在插件运行时自动创建，初始为 `{}`。插件用 `game.getConfig` 读取、`game.setConfigDefault` 写入默认值。\n- `插件数据文件` 目录存放**运行数据**——需要持久化的业务数据（金钱、领地、商店商品）。每个插件有一个以 id 命名的子目录，插件可自由在里面创建任意文件。\n\n### 打包成 zip\n\nzip 里的结构是扁平的三（或四）个文件：\n\n- `manifest.json` —— 插件的元数据，必填。\n- `main.lua` —— 插件的代码，必填（词库类插件则是 `词库.json`）。\n- `docs.md` —— 插件的说明文档，可选。\n- `config.json` —— 插件默认配置，可选；导入时写入配置文件。\n\n`manifest.json` 字段（均用英文键名）：\n\n- `id`：插件唯一标识，只允许用英文/数字/下划线，一旦确定不要更改。它决定三个目录的名字，也是跨插件调用时的名称。\n- `name`：插件的展示名，中文可以。\n- `version`：版本号，形如 `1.0.0`。其它插件可用它做前置版本校验。\n- `type`：插件类型，写 `lua`。\n- `author`：作者名。\n- `description`：一句话功能简介。\n- `pre_plugins`：前置依赖。一个对象，键是所依赖的插件 id，值是最低版本号。没有依赖写空对象 `{}`。\n\n一个最小 manifest 示例：\n\n```json\n{\n  \"id\": \"my_plugin\",\n  \"name\": \"我的插件\",\n  \"version\": \"1.0.0\",\n  \"type\": \"lua\",\n  \"author\": \"me\",\n  \"description\": \"一个示例插件\",\n  \"pre_plugins\": {}\n}\n```\n\n依赖语义：**加载本插件之前，工具箱会先加载并运行被依赖的前置插件**。若前置插件不存在或版本不足，本插件加载失败并被标记为错误状态，不会拖垮整个框架。\n\n### 安装与导入\n\n把 zip 放到插件的 `插件文件` 目录，或在插件管理页选择该 zip 导入。导入后工具箱自动解包并把文件写入对应位置。之后在插件管理页点\"运行\"，插件就加载生效了。\n\n---\n\n## 三、插件的加载与生命周期\n\n当你运行一个插件时，工具箱按顺序做了这些事：\n\n1. **解析前置依赖**。若声明了 `pre_plugins`，先递归加载并运行每个前置插件，保证被依赖插件的代码与数据就绪。\n2. **创建配置文件与数据目录**。确保 `插件配置文件/<id>/<id>.json` 存在（没有就写成 `{}`），确保 `插件数据文件/<id>/` 目录存在。\n3. **读取代码**，把代码放进一个全新的 Lua 状态里执行。\n\n关键概念：**插件源码会在多个场合被\"重新执行\"**。不仅仅加载时执行一次，每当有事件触发、定时任务到期、聊天触发词命中、或别的插件跨插件调用它时，工具箱都会**新建一个 Lua 状态、重新执行一遍插件源码**，再调用对应函数。\n\n好处：每个执行上下文隔离，天然线程安全；插件源码是\"无状态加载 + 每次重跑重建\"，行为可预测。\n\n代价：\n\n- 每次重跑都会重新定义全局函数、重新执行顶层代码。**不要在顶层做昂贵或重复副作用的事情。**\n- 顶层的注册调用（如 `game.registerTrigger`、`events.onChat`、`util.schedule`）在重跑时会被工具箱自动跳过，避免重复注册。内部用一个 `__RE_RUN__` 标记区分\"首次加载\"和\"重跑执行\"。**你不需要手动处理这个标记**。\n- 持久化数据必须放文件里（配置文件或数据目录），不能指望全局变量跨调用存活——全局变量在每次重跑时都会重置。\n\n### 运行时限制与保护\n\n- **单次执行超时 2 分钟**。一次加载/触发/事件/定时回调，从进入 Lua 到返回最多 2 分钟，超时被强制中断并记日志。死循环不会卡死机器人，但会中断报错。\n- **定时任务间隔必须在 0.001 秒 ~ 1 年之间**（`util.schedule`）；`util.setTimeout` 延时必须在 0 ~ 1 年之间。填 0 或负数会直接报错。\n- **并发上限**：同一时刻最多 32 个触发词/事件 handler 在执行，超出排队。玩家刷屏时有背压。\n- **HTTP 响应体上限 10MB**。`game.httpGet/httpPost` 与 `http.*` 拉取超过 10MB 的响应会报错。\n\n---\n\n## 四、全局 API 函数详解\n\n**全局对象一览**：`game`（游戏操作）、`system`（系统/设备）、`api`（跨插件）、`plugin`（插件自身）、`util`（工具/定时）、`bot`（多机器人）、`building`（建筑）、`media`（媒体）、`world`（世界方块）、`player`（玩家数据）、`events`（事件）、`http`（网络）、`web`（网页）。\n\n**通用约定（读前必看）**：\n\n- **多数读操作在出错时会抛 Lua 异常**（不是返回 `nil`），要用 `pcall` 包裹才能容错。例外：`game.promptChoice` 超时/取消返回 `nil`；`player.get`/`player.getXUID` 等查不到的玩家返回空表/空串/`0`。\n- 部分函数依赖全局 `__PLUGIN_ID__`（当前插件 id）。在\"无插件上下文\"的裸环境调用时它们会降级（返回默认值/空串/直接返回），正常插件加载时总可用。\n- 机器人相关调用（`game.*`、`world.block`、`player.getInventory`）操作的是**当前活跃机器人**，用 `bot.select` 切换。\n- 触发词、事件、定时、跨插件调用、网页动作，都是\"**重跑插件源码后按函数名调用 handler**\"。所以 handler 必须在全局作用域定义。\n- **\"底层\"栏说的是游戏内实际发生的事**：对游戏操作类函数，它说明工具箱向游戏发了哪条指令/哪个数据包、服务器怎么响应、结果从响应的哪里读。据此你能预判副作用（如 `getBlockTile`/`getBlockData` 会传送机器人加载区块）、定位失败原因（指令需要 OP、区块未加载、网易服不返回结果），也可以自己在游戏里手动敲同样的指令复现。\n\n---\n\n### 4.1 game —— 游戏操作主入口\n\n`game` 是使用最频繁的对象：发指令、读数据、菜单交互、配置、网络、控制机器人移动。下列方法多数操作\"当前活跃机器人\"。\n\n#### 指令与消息\n\n**`game.sendCommand(cmd)`**\n- 作用：发送一条游戏指令（等价于游戏内执行 `/cmd`），只发不等待结果。\n- 参数：`cmd` — string，必填。\n- 返回：无。\n- 报错：若 sendCommandHook 返回错误则抛 `sendCommand: <err>`。\n- 底层：通过**网易 AI 命令通道**（PyRpc `ExecuteCommandEvent`，命令自动加 `execute run` 前缀）发送指令，不等响应。实际就是在游戏内敲了 `/cmd`。注意：需要 OP 的指令若机器人无 OP，指令会发出但**不生效也不报错**。\n\n**`game.sendTargeted(player, text)`**\n- 作用：只给指定玩家发一条消息，不广播给其他人。`§` 前缀可带颜色（如 `\"§a成功！\"`）。\n- 参数：`player` string 必填；`text` string 必填。\n- 返回：无。\n- 报错：无（底层错误被忽略）。\n- 底层：通过**网易 AI 命令通道**（PyRpc `ExecuteCommandEvent`，命令自动加 `execute run` 前缀）发定向 tellraw：`tellraw @a[name=\"<玩家>\"] {\"rawtext\":[{\"text\":\"...\"}]}`。只发给该玩家、绝不广播；用 `@a[name=...]` 选择器是为了兼容网易服（普通通道在网易不执行）。\n\n**`game.sendChat(target, message)`**\n- 作用：给指定玩家或选择器（如 `@a`）发一条聊天消息。\n- 参数：`target` string 必填；`message` string 必填。\n- 返回：无。\n- 报错：失败抛 `sendChat: <err>`。\n- 底层：通过网易 AI 命令通道发 `tellraw <target> {\"rawtext\":[{\"text\":\"...\"}]}`（target 为 `@a` 或玩家名），文本里的 `\"` 会自动转义。\n\n**`game.sendRichTellraw(msg)`**\n- 作用：发送原生 tellraw 富文本（支持 JSON 样式），常用于公告。\n- 参数：`msg` string 必填。\n- 返回：无。\n- 报错：失败抛 `sendRichTellraw: <err>`。\n- 底层：通过网易 AI 命令通道发 `tellraw @a {\"rawtext\":[{\"text\":\"...\"}]}`，`msg` 里的 `\"` 自动转义后嵌入 JSON。\n\n**`game.sendLines(player, text, maxLines)`**\n- 作用：把长文本**按换行逐条发送**，避免单条超长被截断、或某行含敏感词整段被拦。超行数时先提示\"仅显示前 N 行\"。空行跳过。\n- 参数：`player` string 必填；`text` string 必填；`maxLines` number 可选，默认 50。\n- 返回：无。\n- 报错：无。\n- 底层：把长文本按 `\\n` 切分，逐行用 `sendTargeted` 的定向 tellraw 机制发送；超过 `maxLines` 先提示\"仅显示前 N 行\"，空行跳过。\n\n**`game.sendPacket(typeNameOrId, fieldsTable)`**\n- 作用：发送**任意数据包**（客户端→服务器），用于发起协议交互/测试协议。与 `events.subscribeAll` / AI `wait_packet` 监听形成闭环（发请求包 → 监听服务器响应）。\n- 参数：`typeNameOrId` string（包类型名，如 `\"RequestChunkRadius\"`）**或** number（包协议 ID）；`fieldsTable` table 可选，snake_case 字段（如 `{chunk_radius=4, max_chunk_radius=8}`）。复合字段格式：数字数组（Vec3/BlockPos）、hex 字符串（UUID/字节数组）、Bitset 用比特位数组（如 `{input_data={1,2}}`）。发原始字节：`game.sendPacket(69, {payload_hex=\"0102ff\"})`。\n- 返回：无。\n- 报错：失败抛 `sendPacket: <err>`（未知类型/未知字段/字段类型不符/未连接）。握手/生命周期专用包（Login、ClientToServerHandshake 等）已列入禁止，发送会报错。\n- 底层：`mapToPacket`（packet_send.go，packetToMap 的逆反射填充）→ `abot(L).WritePacket(pk)` → `conn.WritePacket`（自动 header/批次/压缩加密）。字段结构可用 AI `list_packet_schema` 工具查询。\n\n#### AI 组合工具（执行 + 等待）\n\nAI 侧新增三个组合工具（用于\"发指令后观察结果/包/聊天\"的闭环；Lua 插件可自行用 `game.sendPacket` + `events.subscribeAll` 实现等价逻辑）：\n\n- `send_command_wait_output`：执行指令并等待服务器响应（CommandOutput），返回 `{success,is_timeout,note,output_messages:[{success,message,parameters}],raw}`。参数 `command`（必填）、`channel`（ai/console/player，默认 ai）、`timeout` 秒（默认 8，上限 30）、`bot_index`。\n- `run_and_watch_packet`：先执行指令（可选），再监听接下来一段时间的入站数据包（含 CommandOutput/未知包），返回事件数组。参数 `command`（可选）、`packet_type`/`packet_id`/`bot_index` 过滤、`seconds`(1-60)、`max_count`。\n- `run_and_watch_chat`：先执行指令（可选），再监听接下来一段时间的聊天，返回 `[{player,message}]`。参数 `command`（可选）、`keyword`（可选过滤）、`seconds`、`max_count`。\n\n**`game.sendTitle(target, title, subtitle)`**\n- 作用：给玩家显示大标题 + 副标题。\n- 参数：`target`/`title`/`subtitle` 均 string 必填。\n- 返回：无。\n- 报错：失败抛 `sendTitle: <err>`。\n- 底层：通过网易 AI 命令通道发 `titleraw <target> title {\"rawtext\":[{\"text\":\"...\"}]}`；副标题非空时再追加一条 `titleraw <target> subtitle {\"rawtext\":[...]}`。\n\n**`game.sendActionbar(target, text)`**\n- 作用：给玩家显示动作栏消息（物品栏上方那行）。\n- 参数：`target`/`text` string 必填。\n- 返回：无。\n- 报错：失败抛 `sendActionbar: <err>`。\n- 底层：通过网易 AI 命令通道发 `titleraw <target> actionbar {\"rawtext\":[{\"text\":\"...\"}]}`。\n\n**`game.isCmdSuccess(cmd)`**\n- 作用：执行一条指令并判断是否成功，返回布尔。\n- 参数：`cmd` string 必填。\n- 返回：boolean（是否成功）。\n- 报错：失败抛 `isCmdSuccess: <err>`。\n- 底层：通过 **WS 自动化通道**执行指令并**等待 CommandOutput**，命令响应的 `SuccessCount > 0` 即视为成功。无 OP 或语法错误的指令，服务器返回失败输出，此函数返回 `false`。\n\n#### 读取玩家与游戏数据\n\n**`game.getScore(scoreboard, target)`**\n- 作用：读某记分板里某个目标（玩家名）的分数。\n- 参数：`scoreboard` string 必填；`target` string 必填。\n- 返回：number（分数）。\n- 报错：失败抛 `getScore: <err>`。\n- 底层：通过 **WS 自动化通道**执行 `scoreboard players test <目标> <记分板> 0 0`（借用\"分数是否在 0~0 之间\"的判断把分数值带出来）并等待 CommandOutput，从响应的 `Parameters[0]` 读出分数。响应是 `commands.scoreboard.objectiveNotFound`（计分板不存在）、`...players.list.player.empty`（目标不存在）或 `...players.score.notFound`（目标在该记分板无分数）时，分别报对应错误。\n\n**`game.getMultiScore(target)`**\n- 作用：读某目标在所有记分板上的分数。\n- 参数：`target` string 必填。\n- 返回：table，结构 `{player = {记分板名 = 分数, ...}}`。\n- 报错：失败抛 `getMultiScore: <err>`。\n- 底层：通过 **WS 自动化通道**执行 `scoreboard players list <目标>` 并等待 CommandOutput，把响应里逐条输出的\"玩家·记分板·分数\"（`commands.scoreboard.players.list.player.entry` 行）解析成 `{玩家 = {记分板 = 分数}}`。\n\n**`game.setScore(board, target, score)`**\n- 作用：写入记分板，执行 `scoreboard players set`。\n- 参数：`board` string、`target` string、`score` number 均必填。\n- 返回：无。\n- 报错：失败抛 `setScore: <err>`。\n- 底层：拼指令 `scoreboard players set <target> <board> <score>`，通过**网易 AI 命令通道**发出，不等响应。\n\n**`game.getPlayerPos(target)`**\n- 作用：读玩家坐标与所在维度。\n- 参数：`target` string 必填（可为玩家名或 `@a`/`@p` 选择器）。\n- 返回：table `{x, y, z, dimension}`。\n- 报错：失败抛 `getPlayerPos: <err>`。\n- 底层：通过 **WS 自动化通道**执行只读命令 `querytarget <目标>` 并等待响应，解析返回的坐标（玩家脚部位置）并修正成可读值：正数向下取整到两位小数、负数先减 1、Y 再减 1.62（眼睛高度）；俯仰角 pitch 从工具箱维护的玩家缓存补取。`querytarget` 无副作用。\n\n**`game.getPlayerPosXYZ(target)`**\n- 作用：读玩家坐标，直接返回三个数字。\n- 参数：`target` string 必填。\n- 返回：三个 number，依次 x、y、z。\n- 报错：失败抛 `getPlayerPosXYZ: <err>`。\n- 底层：同 `getPlayerPos`——执行 `querytarget` 后只取返回坐标的 x、y、z 三个数。\n\n**`game.getPlayerItem(target, item, specialID)`**\n- 作用：统计玩家背包里某种物品的数量，可带特殊数据 ID。\n- 参数：`target` string、`item` string 必填；`specialID` number 可选，默认 0。\n- 返回：number（数量）。\n- 报错：失败抛 `getPlayerItem: <err>`。\n- 底层：通过 **WS 自动化通道**执行游戏指令 `clear <目标> <物品> <特殊值> 0` 并等待 CommandOutput。**第 4 个参数 `0` 是游戏的\"只统计不清除\"技巧**——`clear` 的数量参数为 0 时不会真的清空物品，只报告玩家拥有多少这种物品（标准做法，可放心用于查数量）。响应为 `commands.clear.success` 时从输出的数量参数得到该物品数量；`commands.clear.failure.no.items`（玩家根本没有这种物品）返回 0；`commands.generic.syntax`（物品 ID 非法）报错。\n\n**`game.getBlockTile(x, y, z)`**\n- 作用：读某坐标的方块名。用安全版：可能先把机器人传送过去加载区块再查，避免远处区块\"未加载\"报错，因此有移动副作用。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：string（方块名/方块 ID）。\n- 报错：失败抛 `getBlockTile: <err>`。\n- 底层：**有移动副作用**：机器人先 `tp` 到目标上方高空（y=150）把该 x,z 的区块加载出来（`testforblock` 只对已加载区块有效，远处直接查会返回 `outOfWorld`），等游戏刻 + 约 400ms 区块就绪后查询，最后传送回原位。查询本身通过 WS 自动化通道执行 `testforblock <x> <y> <z> air`：`SuccessCount > 0` → 该坐标是空气；否则从命令失败输出里解析实际方块名（兼容网易版的参数偏移）。应在独立后台协程中调用（会传送并等待）。\n\n**`game.getBlockTileRaw(x, y, z)`**\n- 作用：直接查询方块，不做传送加载（更快，但区块未加载可能报错）。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：string（方块名）。\n- 报错：失败抛 `getBlockTileRaw: <err>`。\n- 底层：通过 WS 自动化通道执行 `testforblock <x> <y> <z> air`：`SuccessCount > 0` → 空气；否则从失败输出解析实际方块名。**不做传送**，远区块可能因未加载返回 `outOfWorld` 报错。\n\n**`game.getTickingAreaList()`**\n- 作用：读当前加载的常驻区域（ticking area）列表。\n- 参数：无。\n- 返回：table `{区域名 = {dimension, start_x, start_z, end_x, end_z}}`。\n- 报错：失败抛 `getTickingAreaList: <err>`。\n- 底层：通过 **WS 自动化通道**执行 `tickingarea list all-dimensions` 并等待响应，把命令返回的多行文本输出（每维度一组，每组里 `- 名称: (startX, startZ) to (endX, endZ)`）解析成结构化表。\n\n**`game.queryInventory(selector)`**\n- 作用：查询玩家背包物品清单。\n- 参数：`selector` string 必填。\n- 返回：table `{items = {{name, count, slot, damage}, ...}}`。\n- 报错：失败抛 `queryInventory: <err>`。\n- 底层：通过 WS 自动化通道执行网易特有的 `codebuilder_actorinfo inventory <选择器>` 并等待响应，从命令响应的 DataSet（JSON）里解析出 `{name, count, slot, damage}` 物品清单。需要机器人具备网易 AI/指令权限。\n\n**`game.getTarget(selector)`**\n- 作用：解析选择器，返回匹配的玩家名数组。\n- 参数：`selector` string 必填。\n- 返回：table（玩家名字符串数组，1 起索引）。\n- 报错：失败抛 `getTarget: <err>`。\n- 底层：通过 **WS 自动化通道**执行 `testfor <选择器>` 并等待响应，把输出参数里逗号分隔的玩家名列表解析成数组。选择器语法错误（`commands.generic.syntax`）时报错；无匹配返回空表。\n\n**`game.setEffect(player, effect, duration, level, particles)`**\n- 作用：给玩家施加药水效果。\n- 参数：`player` string、`effect` string、`duration` number、`level` number 必填；`particles` boolean 可选，默认 `true`。\n- 返回：无。\n- 报错：失败抛 `setEffect: <err>`。\n- 底层：通过 **WS 自动化通道**执行 `effect <玩家> <效果> <时长秒> <等级> <是否显示粒子>` 并等待响应，响应 `commands.effect.success` 才算成功。`commands.generic.noTargetMatch`（没有匹配目标）时报错；等级上限 255、时长上限 1000000 秒，超出直接报错。\n\n#### 方块 NBT / 方块状态 读写\n\n> 这组函数让插件（和 AI）能**读取**与**写入**游戏内方块的完整数据，包括方块实体 NBT（命令方块指令、箱子物品、告示牌文字、旗帜图案）和方块状态（朝向/开关/是否点亮等）。\n> 读取统一基于\"结构保存\"（structure save）机制，一次读取即可同时拿到 名称 + 状态 + NBT。\n> 底层实现在 `nbt_world_api.go`；**AI 通过 `game_call` 工具也能调用同样的能力**（函数名一致）。\n\n**`game.getBlockData(x, y, z)`**\n- 作用：读某坐标方块的完整数据（名称 + 方块状态 + 方块实体 NBT）。读取命令方块指令、箱子物品、告示牌文字、旗帜图案等都从这里入手。会先把机器人传送过去加载区块（有移动副作用）。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：table `{name = 方块名, states = {状态键 = 值, ...}, nbt = {NBT 键 = 值, ...}}`（无 NBT 时 `nbt` 省略）。\n- 报错：失败抛 `getBlockData: <err>`。\n- 底层：传送加载区块后，用游戏的**结构保存**机制读取：先通过 WS 自动化通道执行 `structure save \"<随机名>\" <区域>` 把该方块连同方块实体 NBT 存成一个临时结构，再发 `StructureTemplateDataRequest`（ExportFromSave）把结构数据拉回来，解析 `block_palette`（名称+状态）与 `block_position_data`（NBT）得到完整数据。有移动副作用。\n\n**`game.getBlockNBT(x, y, z)`**\n- 作用：只读方块实体 NBT。命令方块指令在 `nbt.Command`，箱子物品在 `nbt.Items`，告示牌文字在 `nbt.FrontText.Text`。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：table，无 NBT 时返回 `nil`。\n- 报错：失败抛 `getBlockNBT: <err>`。\n- 底层：同 `getBlockData` 的结构保存机制（传送 + `structure save` + `StructureTemplateDataRequest`），只保留解析出的 NBT 部分。有移动副作用。\n\n**`game.getBlockState(x, y, z)`**\n- 作用：读方块名称与方块状态（朝向/是否点亮/开关等），不含 NBT。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：table `{name = 方块名, states = {...}}`。\n- 报错：失败抛 `getBlockState: <err>`。\n- 底层：同 `getBlockData` 的结构保存机制，只保留名称与方块状态，丢弃 NBT。有移动副作用。\n\n**`game.getRegionBlockData(x, y, z, sx, sy, sz)`**\n- 作用：读一块区域（起点 `x,y,z`，尺寸 `sx×sy×sz`）所有方块的名称+状态+NBT，一次结构保存返回，适合整片区域/区块探查。\n- 参数：6 个 number 均必填，尺寸需为正。\n- 返回：table，键为 `\"x,y,z\"` 绝对坐标，值为 `{name, states, nbt}`。\n- 报错：失败抛 `getRegionBlockData: <err>`。\n- 底层：机器人先传送到区域中心上方加载区块，再**一次结构保存**（`structure save` + `StructureTemplateDataRequest`）把整片区域拉回，按 `block_indices` 线性索引还原成 `\"x,y,z\"` → 方块数据的映射。有移动副作用。\n\n**`game.setBlock(x, y, z, name, states)`**\n- 作用：放置一个普通方块，可带方块状态字符串。\n- 参数：`name` string 必填；`states` string 可选（如 `[\"facing_direction\"=3]`，默认空）。\n- 返回：无。\n- 报错：失败抛 `setBlock: <err>`。\n- 底层：通过**网易 AI 命令通道**发 `setblock <x> <y> <z> <方块> <states>`（PyRpc `ExecuteCommandEvent`，权限比普通命令通道高，在网易租赁服更可靠），发完稍等片刻返回。\n\n**`game.placeNBTBlock(x, y, z, name, states, nbtTable)`**\n- 作用：放置一个带 NBT 的特殊方块（命令方块/结构方块/告示牌/箱子/旗帜等），自动按方块类型选择最快可靠的放置方式：\n  - 命令方块：`{Command = \"say hi\", Conditional = 1, TickDelay = 0}`；\n  - 告示牌：`{FrontText = {Text = \"你好\", Color = \"black\"}, ...}`；\n  - 箱子：`{Items = {{Count = 1, Name = \"minecraft:diamond\", Slot = 0}, ...}}`。\n- 参数：`name` string 必填；`states` string 可选；`nbtTable` table 可选。\n- 返回：无。\n- 报错：失败抛 `placeNBTBlock: <err>`。\n- 底层：按 `building.ClassifyBlock` 对方块分类后选择不同游戏机制：命令方块/结构方块 → **直接发 NBT 包**（快）；告示牌 → 直接发 `PlaceSign` 包（快）；重 NBT 方块（箱子/旗帜等）→ 机器人**放到远程工作台 + 结构复制**（慢，需要结构权限）；普通方块 → `setblock` 指令。\n\n**`game.setBlockState(x, y, z, statesTable)`**\n- 作用：修改某方块的方块状态并保留原 NBT（如把命令方块设为条件模式、把方块朝向改朝北）。会先读当前方块，合并新状态后重新放置。\n- 参数：`statesTable` table 必填，键 = 状态名，值 = 数值/布尔（如 `{conditional_bit = 1, facing_direction = 3}`）。\n- 返回：无。\n- 报错：失败抛 `setBlockState: <err>`。\n- 底层：先按 `getBlockData` 的结构保存机制读回当前方块的名称、状态与 NBT，把新状态合并进去后，再按 `placeNBTBlock` 的方式**重新放置**该方块（保留原 NBT）。有移动副作用（需要传送读取）。\n\n> **注意**：箱子/旗帜这类\"重 NBT 方块\"写入在网易下走远程工作台 + 结构复制，较慢且需要结构权限；命令方块/告示牌直接发包，快。读取和写入都会传送机器人加载区块，属正常副作用。\n\n#### 玩家交互（菜单与输入）\n\n**`game.showMenu(player, title, options)`**\n- 作用：给玩家显示一个聊天栏菜单（标题 + 若干选项），只展示不等待。\n- 参数：`player` string、`title` string 必填；`options` table（字符串数组）必填。\n- 返回：无。\n- 报错：无。\n- 底层：通过网易 AI 命令通道给该玩家发**多条定向 tellraw**（绝不广播）：标题一条，每个选项一条 `§e序号. 选项文字`。\n\n**`game.promptChoice(player, title, options, timeoutSec)`**\n- 作用：显示菜单并**阻塞等待玩家选择**，返回所选选项下标。\n- 参数：`player`/`title` string、`options` table 必填；`timeoutSec` number 可选，默认 30。\n- 返回：number 或 nil。成功返回 **1 起** 下标（第一个是 1）；超时/取消/无效输入返回 `nil`。\n- 报错：失败抛 `promptChoice: <err>`。\n- 底层：先用 `showMenu` 把菜单发给玩家，再用 `waitMsg` 的机制**阻塞等待该玩家的下一条聊天消息**，把它解析成序号（支持 `1`、`1.`、`1、` 等写法）。超时或输入无效返回 `nil`。\n\n**`game.waitMsg(player, timeoutSec)`**\n- 作用：**阻塞等待玩家在聊天栏发一条消息**，返回内容。用于要输入（领地、数量等）。\n- 参数：`player` string 必填；`timeoutSec` number 可选，默认 30。\n- 返回：string（收到的消息）。超时返回 `nil`。\n- 报错：失败抛 `waitMsg: <err>`。\n- 底层：在机器人**收包循环**里为该玩家注册一个\"等待通道\"，玩家下一条聊天消息到达时投递给等待者。它**独占**该玩家的消息——同一玩家已有活跃等待会话时，新消息会被它消费掉，`onChat` 等其它 handler 收不到。\n\n**`game.registerTrigger(wordsTable, handlerName)`**\n- 作用：注册触发词。任一玩家发言命中任意词时，临时虚拟机**重跑插件源码**并调用全局函数 `handlerName(player, args)`。\n- 参数：`wordsTable` table（字符串数组）必填；`handlerName` string（全局函数名）必填。\n- 返回：无。\n- 报错：无显式报错。\n- 底层：在聊天触发注册表里登记触发词；此后任一玩家聊天消息命中触发词时，新建 Lua 状态重跑插件源码并调用 handler。重跑上下文自动跳过重复注册。\n\n#### 配置与数据目录\n\n**`game.getConfig(key, default)`**\n- 作用：读本插件配置文件里某个键，缺失返回 `default`。\n- 参数：`key` string 必填；`default` 任意类型可选。\n- 返回：配置值（或 `default`）。\n- 报错：无（读失败回退默认）。\n- 底层：读取本插件配置文件 `插件配置文件/<id>/<id>.json`，命中则把值转成 Lua 返回，否则返回 `default`。依赖 `__PLUGIN_ID__`。\n\n**`game.setConfigDefault(table)`**\n- 作用：把配置文件中**缺失的键**写入默认值（已有的键不覆盖）。\n- 参数：`table` 必填（键值任意类型）。\n- 返回：无。\n- 报错：无（写失败忽略）。\n- 底层：先读 `插件配置文件/<id>/<id>.json`，把其中缺失的键补写进去（已存在的键不动）。依赖 `__PLUGIN_ID__`。\n\n**`game.dataDir()`**\n- 作用：返回本插件数据目录的完整路径，即 `插件数据文件/<id>/`。\n- 参数：无。\n- 返回：string。`__PLUGIN_ID__` 为空时返回空串。\n- 报错：无。\n- 底层：`pluginController.DataDir(id)`。\n\n#### 网络与 JSON\n\n**`game.httpGet(url)`**\n- 作用：发起 HTTP GET 请求，返回响应体文本。\n- 参数：`url` string 必填。\n- 返回：string（响应体）。\n- 报错：失败抛 `httpGet: <err>`。\n- 底层：发起一次真实的 HTTP GET 请求，把响应体按 UTF-8 文本返回；网络错误或非 2xx 状态码都会抛错。\n\n**`game.httpPost(url, body, headers)`**\n- 作用：发起 HTTP POST 请求，可带自定义请求头。\n- 参数：`url` string 必填；`body` string 可选，默认 `\"\"`；`headers` table（键值均为 string）可选。\n- 返回：string（响应体）。\n- 报错：失败抛 `httpPost: <err>`。\n- 底层：发起一次真实的 HTTP POST 请求（可带请求头与请求体），把响应体按 UTF-8 文本返回；网络错误或非 2xx 状态码都会抛错。\n\n**`game.jsonEncode(v)`**\n- 作用：把任意 Lua 值编码成 JSON 字符串。\n- 参数：`v` 任意类型。\n- 返回：string（JSON）。\n- 报错：序列化失败抛 `jsonEncode: <err>`。\n- 底层：把 Lua 值映射成对应的 JSON 类型（表→对象/数组、数字/字符串/布尔原样）后编码成字符串。\n\n**`game.jsonDecode(s)`**\n- 作用：把 JSON 字符串解析成 Lua 值。\n- 参数：`s` string 必填。\n- 返回：任意 Lua 值（表/数字/字符串/布尔）。\n- 报错：解析失败抛 `jsonDecode: <err>`。\n- 底层：把 JSON 解析成对应 Lua 类型（对象→表、数组→1 起索引的表、数字/字符串/布尔原样返回）。\n\n> 这几个是挂在 `game` 上的轻量便捷方法；需要完整请求控制（超时、多种方法、错误码）时用 4.12 节的 `http` 模块。\n\n#### 机器人移动与飞行（作用于当前活跃机器人）\n\n**`game.teleport(x, y, z)`**\n- 作用：传送机器人到绝对坐标。\n- 参数：`x`/`y`/`z` number 必填。\n- 返回：无。\n- 报错：失败抛 `teleport: <err>`。\n- 底层：发一个 `MovePlayer` 包（`MoveModeTeleport`）把机器人瞬间传送到目标坐标——**不是 `/tp` 指令**，是客户端传送包，服务器按传送处理。\n\n**`game.move(dx, dy, dz)`**\n- 作用：让机器人相对当前位置移动。\n- 参数：`dx`/`dy`/`dz` number 必填。\n- 返回：无。\n- 报错：失败抛 `move: <err>`。\n- 底层：在当前坐标上累加位移后发一个 `MovePlayer` 包（`MoveModeTeleport`），瞬间完成相对移动。\n\n**`game.rotate(pitch, yaw, seconds?)`**\n- 作用：设置机器人朝向。\n- 参数：`pitch`/`yaw` number 必填；`seconds` number 可选——省略或 `0` 时**立即转到**目标角度，`>0` 时在 seconds 秒内**平滑转动**过去（yaw 走最短路径，如从 350° 转到 10° 只转 20°）。\n- 返回：无。\n- 报错：失败抛 `rotate: <err>`。\n- 底层：只更新机器人本地视角状态，心跳（50ms）通过 `PlayerAuthInput` 包把新视角发送到服务器。秒数 `>0` 时先在本地逐帧插值，再由心跳带出中间帧。\n\n**`game.jump()`**\n- 作用：让机器人跳一下。\n- 参数：无。\n- 返回：无。\n- 报错：失败抛 `jump: <err>`。\n- 底层：模拟按一次跳跃键：置位跳跃标志让心跳携带跳跃输入，约 200ms 后自动松开。\n\n**`game.sneakStart()` / `game.sneakStop()`**\n- 作用：开始 / 停止潜行。\n- 参数：无。\n- 返回：无。\n- 报错：失败抛 `sneakStart/sneakStop: <err>`。\n- 底层：设置潜行标志，心跳持续携带潜行输入；`sneakStop` 额外发一个带 `StopSneaking` 标志的 `PlayerAuthInput` 包。\n\n**`game.sprintStart()` / `game.sprintStop()`**\n- 作用：开始 / 停止疾跑。\n- 参数：无。\n- 返回：无。\n- 报错：失败抛 `sprintStart/sprintStop: <err>`。\n- 底层：设置奔跑标志，心跳持续携带奔跑输入。\n\n**`game.flyStart()` / `game.flyStop()`**\n- 作用：开始 / 停止飞行。\n- 参数：无。\n- 返回：无。\n- 报错：失败抛 `flyStart/flyStop: <err>`。\n- 底层：把机器人切换为飞行/降落：优先走游戏接口的飞行控制（运动能力包），不可用时回退为发送带飞行标志的 `PlayerAuthInput` 包。\n\n**`game.stopMove()`**\n- 作用：停止机器人当前移动。\n- 参数：无。\n- 返回：无。\n- 报错：失败抛 `stopMove: <err>`。\n- 底层：关闭持续移动的本地循环并清空移动输入标志，心跳随之不再携带方向输入。\n\n**`game.getBotPos()`**\n- 作用：读取当前活跃机器人自身坐标。\n- 参数：无。\n- 返回：table `{x, y, z}`。\n- 报错：无。\n- 底层：通过 WS 自动化通道执行只读命令 `querytarget @s` 并解析坐标、朝向、维度；pitch 与飞行/疾跑状态取本地缓存。\n\n---\n\n### 4.2 system —— 系统与设备交互\n\n`system` 的函数（除 `platform` 外）都通过 JNI 桥**同步**调用 Android 原生能力。桌面环境不支持，会返回错误 `\"桌面环境不支持系统交互\"`。`system.shell` 需要 Shizuku 授权。\n\n**`system.platform()`**\n- 作用：返回当前运行平台。\n- 参数：无。\n- 返回：string——`\"android\"` 或 `\"desktop\"`。\n- 报错：无。\n- 底层：`getPlatformName()`（不经 JNI 桥）。\n\n**`system.call(method, paramsTable?)`**\n- 作用：通用底层透传——把 `method` 和参数表交给 Java 分发执行，返回任意结果。已支持的方法：`shell`、`shizukuStatus`、`shizukuRequest`、`vibrate`、`notify`、`launchApp`；未知方法返回 `{\"ok\":false,\"error\":\"unknown method: ...\"}`。\n- 参数：`method` string 必填；`paramsTable` table 可选。\n- 返回：任意 Lua 值（Java 返回 JSON 解码结果）；无返回推 `nil`。\n- 报错：参数序列化失败或桥调用失败抛 `system.call: <err>`。\n- 底层：参数 `json.Marshal` → `callAndroidSystem` → JNI → Java `FloatingBridge.call` switch 分发。\n\n**`system.shell(cmd)`**\n- 作用：以 Shizuku(ADB) 身份执行一条 shell 命令。\n- 参数：`cmd` string 必填。\n- 返回：table `{ok=bool, exit=number, stdout=string, stderr=string, uid=number, error?=string}`。命令本身失败不抛异常，走 `ok=false`。\n- 报错：仅桥调用失败抛 `system.shell: <err>`。\n- 底层：参数 `{\"command\":cmd}` → JNI → Java `runShell`：空命令/Shizuku 未运行/未授权各有明确错误；否则经反射调 `Shizuku.newProcess` 执行 `/system/bin/sh -c <cmd>`，读 stdout/stderr、取退出码与 uid。\n\n**`system.shizukuStatus()`**\n- 作用：查询 Shizuku 运行状态与授权情况。\n- 参数：无。\n- 返回：table `{available=bool, granted=bool, uid=number}`（失败时 uid=-1）。\n- 报错：桥调用失败抛 `system.shizukuStatus: <err>`。\n- 底层：JNI → Java `shizukuStatusJson`：`Shizuku.pingBinder()`、`checkSelfPermission()==GRANTED`、`getUid()`。\n\n**`system.shizukuRequest()`**\n- 作用：弹出系统授权对话框，申请 Shizuku ADB 权限。\n- 参数：无。\n- 返回：table `{ok=bool, requested=bool, error?=string}`。\n- 报错：桥调用失败抛 `system.shizukuRequest: <err>`。\n- 底层：JNI → Java `requestShizukuPermission`：pingBinder 失败返回未运行；否则 `Shizuku.requestPermission()` 弹授权框。\n\n**`system.vibrate(ms?)`**\n- 作用：触发手机震动（**不需要** Shizuku/ADB 权限）。\n- 参数：`ms` number 可选，默认 500（毫秒）。\n- 返回：table `{ok=true}`；异常时 `{ok=false, error=...}`。\n- 报错：桥调用失败抛 `system.vibrate: <err>`。\n- 底层：参数 `{\"ms\":ms}` → JNI → Java `vibrate`（Vibrator）。\n\n**`system.notify(title, body?)`**\n- 作用：发系统状态栏通知（**不需要** Shizuku/ADB 权限）。\n- 参数：`title` string 必填；`body` string 可选，默认 `\"\"`。\n- 返回：table `{ok=true}`；异常时 `{ok=false, error=...}`。\n- 报错：桥调用失败抛 `system.notify: <err>`。\n- 底层：参数 `{\"title\",\"body\"}` → JNI → Java `postDirectNotification`。\n\n---\n\n### 4.3 api —— 跨插件调用\n\n**`api.require(id)`**\n- 作用：跨插件调用另一个插件导出的函数。返回一个带 `__index` 元方法的**表**；访问其任意键会懒生成一个调用 stub。\n- 参数：`id` string 必填——目标插件 id。\n- 返回：目标插件已加载 → 返回 stub 表；未加载 → 返回 `nil`。\n- 报错：`id` 非 string 抛类型错误；调用 stub 时若目标插件未导出 `plugin_api` / 无该导出函数 / 重跑失败，抛对应错误。\n- 底层：访问 `api.require(id).someFunc` 得到 stub；调用时参数 `luaToGo`+`json.Marshal` → `callPluginFunction`（新建 LState 重跑目标插件源码 → 取全局 `plugin_api.someFunc` → 调用）→ 结果 `jsonDecodeGo`+`goToLua` 回传。目标函数返回 nil/空时返回 `nil`。\n\n**调用方式示例**：\n```lua\nlocal core = api.require(\"core_utils\")  -- 依赖 core_utils 导出 plugin_api.money_get\nlocal bal = core.money_get(player)      -- 调用它\n```\n\n---\n\n### 4.4 plugin —— 插件自身上下文\n\n**`plugin.id()`**\n- 作用：返回当前插件的 id 字符串。\n- 参数：无。\n- 返回：string。\n- 报错：无。\n- 底层：读全局 `__PLUGIN_ID__`。\n\n**`plugin.dependencies()`**\n- 作用：返回当前插件的依赖声明（`pre_plugins`）。\n- 参数：无。\n- 返回：表（原样透传全局 `plugin_dependencies` 的值）。\n- 报错：无。\n- 底层：读全局 `plugin_dependencies`。\n\n---\n\n### 4.5 util —— 通用工具与后台定时任务\n\n#### 时间\n\n**`util.now()`**\n- 作用：返回当前本地时间。\n- 参数：无。\n- 返回：string，格式固定 `\"2006-01-02 15:04:05\"`。\n- 报错：无。\n- 底层：`time.Now().Format(\"2006-01-02 15:04:05\")`。\n\n**`util.timestamp()`**\n- 作用：返回当前 Unix 秒级时间戳。\n- 参数：无。\n- 返回：number。\n- 报错：无。\n- 底层：`time.Now().Unix()`。\n\n**`util.time_fmt(ts?)`**\n- 作用：把 Unix 时间戳格式化为可读的本地时间。\n- 参数：`ts` number 可选，默认当前时间戳。\n- 返回：string。\n- 报错：无。\n- 底层：`time.Unix(ts,0).Format(\"2006-01-02 15:04:05\")`。\n\n#### JSON 与文件\n\n**`util.json_load(path)`**\n- 作用：读取文件并解析为 JSON 对象。\n- 参数：`path` string 必填。\n- 返回：任意 Lua 值（表/数字/字符串…）。数字用 `UseNumber()` 解码避免精度损失。\n- 报错：读文件失败或 JSON 解析失败抛 `json_load: <err>`。\n- 底层：`os.ReadFile` + `json.Decoder`（`UseNumber`）→ `goToLua`。\n\n**`util.json_write(path, data)`**\n- 作用：把任意 Lua 值序列化为带缩进的 JSON 写入文件，自动建父目录。\n- 参数：`path` string 必填；`data` 任意类型必填。\n- 返回：boolean `true`。\n- 报错：建目录/序列化/写文件失败抛 `json_write: <err>`。\n- 底层：`os.MkdirAll` + `json.MarshalIndent(data,\"\",\"  \")` + `os.WriteFile`。\n\n**`util.read_file(path)`**\n- 作用：读取文件全部内容按字符串返回。\n- 参数：`path` string 必填。\n- 返回：string。\n- 报错：读取失败抛 `read_file: <err>`。\n- 底层：`os.ReadFile`。\n\n**`util.write_file(path, content)`**\n- 作用：把字符串写入文件，自动建父目录，权限 0644。\n- 参数：`path` string、`content` string 必填。\n- 返回：boolean `true`。\n- 报错：建目录/写文件失败抛 `write_file: <err>`。\n- 底层：`os.MkdirAll` + `os.WriteFile(path, []byte(content), 0644)`。\n\n#### 字符串\n\n**`util.strip_color(text)`**\n- 作用：去掉文本里的 Minecraft 颜色/格式码（`§` 与 `&` 及其后一个字符）。\n- 参数：`text` string 必填。\n- 返回：string。\n- 报错：无。\n- 底层：手写循环用 `strings.Builder` 逐字节过滤。\n\n**`util.split(str, sep)`**\n- 作用：按分隔符切分字符串为数组。\n- 参数：`str` string、`sep` string 必填。\n- 返回：table（字符串数组，1 起索引）。\n- 报错：无。\n- 底层：`strings.Split` + `RawSetInt`。\n\n**`util.join(tbl, sep)`**\n- 作用：把 table 的所有值转字符串后用分隔符拼接。注意：遍历整表，非数组顺序不一定与下标一致。\n- 参数：`tbl` table、`sep` string 必填。\n- 返回：string。\n- 报错：无。\n- 底层：`t.ForEach` + `LVAsString` + `strings.Join`。\n\n**`util.trim(str)`**\n- 作用：去除字符串两端空白。\n- 参数：`str` string 必填。\n- 返回：string。\n- 报错：无。\n- 底层：`strings.TrimSpace`。\n\n#### 数值\n\n**`util.floor(n)` / `util.ceil(n)` / `util.round(n)`**\n- 作用：向下 / 向上 / 四舍五入取整。\n- 参数：`n` number 必填。\n- 返回：number。\n- 报错：非数值抛类型错误。\n- 底层：`math.Floor` / `math.Ceil` / `math.Round`（`round` 是 Go 的\"四舍六入五成双\"，对 0.5 特判）。\n\n**`util.pos(str)`**\n- 作用：把空格分隔的坐标字符串（如 `\"100 64 200\"`）解析成坐标表，最多取前 3 个 token，缺失项补 0。\n- 参数：`str` string 必填。\n- 返回：table `{x=number, y=number, z=number}`。\n- 报错：无。\n- 底层：`strings.Fields` + `strconv.ParseFloat`。\n\n#### 定时任务\n\n**`util.schedule(intervalSec, handlerName)`**\n- 作用：注册一个按固定间隔重复调用的后台定时任务，每触发一次就重跑源码并调用 `handlerName`。\n- 参数：`intervalSec` number 必填，钳制在 `[0.001, 31536000]`（1 年）；`handlerName` string 必填。\n- 返回：number（任务 id，用于 `util.cancel`）。重跑上下文返回 0 且不注册。\n- 报错：间隔超范围抛 `schedule: 间隔需在 0.001~... 秒之间`。\n- 底层：`newSchedJob(oneshot=false)` + goroutine `runSchedLoop` 用 `time.NewTicker` 周期重跑 handler。\n\n**`util.setTimeout(sec, handlerName)`**\n- 作用：注册一个一次性定时任务，延时后调用 `handlerName` 一次。\n- 参数：`sec` number 必填，允许 0（立即触发），上限 1 年；`handlerName` string 必填。\n- 返回：number（任务 id）。重跑上下文返回 0 不注册。\n- 报错：延时超出 `[0, 31536000]` 抛 `setTimeout: 延时需在 0~... 秒之间`。\n- 底层：`newSchedJob(oneshot=true)` + goroutine 用 `time.NewTimer`。\n\n**`util.cancel(id)`**\n- 作用：取消一个已注册的定时任务（schedule/setTimeout）。\n- 参数：`id` number 必填。\n- 返回：boolean——`true` 找到并取消，`false` 不存在。\n- 报错：无。\n- 底层：`cancelSchedJob(int64(id))`，关闭任务的 cancel channel。\n\n---\n\n### 4.6 bot —— 多机器人舰队与路由\n\n**`bot.select(nameOrIndex)`**\n- 作用：切换后续 `game.*` / `world.*` 调用的目标机器人。\n- 参数：`nameOrIndex` string 必填（机器人名或索引的字符串形式）。\n- 返回：boolean `true`。\n- 报错：未找到机器人抛 `bot.select: 未找到机器人 <名称>`。\n- 底层：`selectBot(L, sel)`。\n\n**`bot.current()`**\n- 作用：返回当前活跃机器人的名字与坐标。\n- 参数：无。\n- 返回：table `{name, x, y, z}`；无活跃机器人返回空表；坐标查询失败省略 x/y/z。\n- 报错：无。\n- 底层：从舰队管理器读当前选中的机器人名，再通过 WS 自动化通道执行 `querytarget @s` 取该机器人的坐标。\n\n**`bot.count()`**\n- 作用：返回在线机器人数量。\n- 参数：无。\n- 返回：number。\n- 报错：无。\n- 底层：`GetFleetBots()`。\n\n**`bot.list()`**\n- 作用：列出在线机器人及坐标。\n- 参数：无。\n- 返回：table，1 起索引，每个元素 `{name, x, y, z}`（坐标查询失败省略坐标字段）。\n- 报错：无。\n- 底层：`GetFleetBots()` 遍历 + `QueryPosition()`。\n\n**`bot.status()`**\n- 作用：返回每个机器人的连接状态、是否 OP、错误信息。\n- 参数：无。\n- 返回：table，1 起索引，每个元素 `{index, name, connected, is_op, error?}`（error 仅非空时存在）。\n- 报错：无。\n- 底层：`FleetStatus()`。\n\n---\n\n### 4.7 building —— 建筑结构解析\n\n**`building.detect(path)`**\n- 作用：检测建筑文件的格式。\n- 参数：`path` string 必填。\n- 返回：string（格式名：`.mcstructure` / `.schematic` / `.mcworld` / `.bdx`）。\n- 报错：非字符串抛类型错误。\n- 底层：`building.DetectFormat(path)`。\n\n**`building.parse(path)`**\n- 作用：加载并解析建筑结构文件，返回尺寸、方块统计、NBT、是否含命令方块。\n- 参数：`path` string 必填。\n- 返回：table `{size={x,y,z}, blocks=number, nbt=number, has_command=boolean}`（`blocks` 为非空气方块数，`nbt` 为 NBT 方块数）。\n- 报错：加载失败抛 `building.parse: <err>`。\n- 底层：`building.LoadStructureFile(path)`，遍历方块计数，读 `NBTBlocks`/`HasCommand`。\n\n**`building.isAir(name)` / `building.isWater(name)` / `building.isLava(name)` / `building.isCommandBlock(name)`**\n- 作用：判断方块名是否为空气 / 水 / 岩浆 / 命令方块。\n- 参数：`name` string 必填（方块名）。\n- 返回：boolean。\n- 报错：无。\n- 底层：`building.IsAirBlock/IsWaterBlock/IsLavaBlock/IsCommandBlock(name)`。\n\n**`building.closestColor(r, g, b)`**\n- 作用：按 CIELAB 感知色差，匹配给定 RGB 最接近的颜色方块。\n- 参数：`r`/`g`/`b` number 必填（0-255）。\n- 返回：string（最接近的颜色方块名）。\n- 报错：非数值抛类型错误。\n- 底层：`media.ClosestBlockForColor(r, g, b)`。\n\n---\n\n### 4.8 media —— 媒体处理\n\n**`media.imageToAscii(path, maxW?)`**\n- 作用：把图片文件转成 ASCII 字符画行数组。\n- 参数：`path` string 必填；`maxW` number 可选，默认 60。\n- 返回：table（字符串数组，1 起索引，每行一个 ASCII 串）。\n- 报错：打开/解码/转换失败抛 `media.imageToAscii: <err>`。\n- 底层：`os.Open` + `image.Decode`（支持 gif/jpeg/png）→ `media.ImageToASCII(img, maxW)`。\n\n**`media.noteToPitch(note)`**\n- 作用：把 MIDI 音符号换算为频率（Hz）。\n- 参数：`note` number 必填（强转 `uint8`）。\n- 返回：number（音高频率）。\n- 报错：非数值抛类型错误。\n- 底层：`media.NoteToPitch(uint8(note))`。\n\n**`media.parseMidi(path)`**\n- 作用：解析 MIDI 文件，返回格式/轨道/分辨率/速度及音符列表。\n- 参数：`path` string 必填。\n- 返回：table `{format, tracks, division, tempo, notes={{tick, channel, note, velocity, duration, sound}}}`（`sound` 仅非空时出现）。\n- 报错：读文件/解析失败抛 `media.parseMidi: <err>`。\n- 底层：`os.ReadFile` → `media.ParseMIDIFile(data)`。\n\n---\n\n### 4.9 world —— 世界方块查询\n\n**`world.block(x, y, z)`**\n- 作用：查询世界某坐标的方块名（需要机器人连接，目标为当前活跃机器人）。\n- 参数：`x`/`y`/`z` number 必填（整数坐标）。\n- 返回：string（方块名）。\n- 报错：查询失败抛 `world.block: <err>`；参数非整数抛类型错误。\n- 底层：同 `game.getBlockTile`——机器人先传送加载区块，再执行 `testforblock <x> <y> <z> air` 判断方块名。**有移动副作用**（会把当前活跃机器人传送过去再传回）。\n\n---\n\n### 4.10 player —— 玩家数据\n\n所有 `player.*` 读的是工具箱维护的**玩家信息缓存**，不向游戏发指令。缓存靠服务器下发的 `PlayerList`/`AddPlayer`/`UpdateAbilities` 等数据包实时维护；网易租赁服不发 PlayerList 包时，后台会用 `/list` + `querytarget` 命令**轮询**补齐（因此这类服上有数秒延迟）。\n\n**`player.get(name)`**\n- 作用：按名字查玩家信息。\n- 参数：`name` string 必填。\n- 返回：table `{name, xuid, unique_id, is_op, online, dimension, x, y, z, held_item?}`（`held_item` 仅非空时出现，为网络 ID）。玩家不存在返回**空表**（不是 nil）。\n- 报错：`name` 非 string 抛类型错误。\n- 底层：直接查玩家缓存表，不向游戏发指令。\n\n**`player.getXUID(name)`**\n- 作用：查玩家 XUID。\n- 参数：`name` string 必填。\n- 返回：string；玩家不存在返回**空串**。\n- 报错：`name` 非 string 抛类型错误。\n- 底层：直接查玩家缓存表的 XUID 字段。\n\n**`player.getUniqueID(name)`**\n- 作用：查玩家实体唯一 ID。\n- 参数：`name` string 必填。\n- 返回：number；玩家不存在返回 **0**。\n- 报错：`name` 非 string 抛类型错误。\n- 底层：直接查玩家缓存表的实体唯一 ID 字段。\n\n**`player.isOP(name)`**\n- 作用：判断玩家是否 OP。\n- 参数：`name` string 必填。\n- 返回：boolean（玩家存在且为 OP 才为 true，含不存在时返回 false）。\n- 报错：`name` 非 string 抛类型错误。\n- 底层：直接查玩家缓存表（`IsOP` 由 `UpdateAbilities`/`AddPlayer` 等数据包维护）。\n\n**`player.list()`**\n- 作用：列出全部在线玩家信息表。\n- 参数：无。\n- 返回：table（1 起索引，每个元素是 `player.get` 同款信息表）。\n- 报错：无。\n- 底层：遍历玩家缓存表。\n\n**`player.count()`**\n- 作用：返回在线玩家数量。\n- 参数：无。\n- 返回：number。\n- 报错：无。\n- 底层：玩家缓存表当前条数。\n\n**`player.getInventory(name)`**\n- 作用：走当前活跃机器人查询某玩家背包物品清单。\n- 参数：`name` string 必填。\n- 返回：table `{items = {{name, count, slot, damage}, ...}}`。\n- 报错：失败抛 `player.getInventory: <err>`。\n- 底层：同 `game.queryInventory`——通过 WS 自动化通道执行网易特有命令 `codebuilder_actorinfo inventory <玩家名>`，从响应 DataSet（JSON）解析物品清单。\n\n---\n\n### 4.11 events —— 事件系统\n\n所有 `events.*` 都是**回调注册**：参数传一个**函数名（string）**，不是函数字面量。事件触发时新建临时 LState 重跑插件源码，再按函数名调用 handler。注册回调返回 0 个值。同插件同 handler 自动去重；重跑上下文跳过注册。\n\n**`events.onChat(handlerName)`**\n- 作用：注册聊天事件处理器。\n- 参数：`handlerName` string 必填，回调签名 `onChat(player, msg)`——触发传 2 参：`player` string（玩家名）、`msg` string（聊天内容）。\n- 返回：无。\n- 报错：`handlerName` 非 string 抛类型错误。\n- 底层：`registerEvent(&evChat, L)`；触发 `fireChatEvent` → `runEventHandlers`。实时。\n\n**`events.onJoin(handlerName)`**\n- 作用：注册玩家加入事件处理器。\n- 参数：`handlerName` string 必填，回调签名 `onJoin(player)`——1 参 `player` string。\n- 返回：无。\n- 报错：`handlerName` 非 string 抛类型错误。\n- 底层：`registerEvent(&evJoin, L)`；由后台 5 秒玩家列表轮询差量触发（有约几秒延迟）。\n\n**`events.onLeave(handlerName)`**\n- 作用：注册玩家离开事件处理器。\n- 参数：`handlerName` string 必填，回调签名 `onLeave(player)`——1 参 `player` string。\n- 返回：无。\n- 报错：`handlerName` 非 string 抛类型错误。\n- 底层：`registerEvent(&evLeave, L)`；由 5 秒轮询差量触发。\n\n**`events.onBotReady(handlerName)`**\n- 作用：注册机器人就绪事件处理器。\n- 参数：`handlerName` string 必填，回调签名 `onBotReady()`——0 参。\n- 返回：无。\n- 报错：`handlerName` 非 string 抛类型错误。\n- 底层：`registerEvent(&evBotReady, L)`。\n\n**`events.onPacket(handlerName)`**\n- 作用：注册数据包事件处理器。\n- 参数：`handlerName` string 必填，回调签名 `onPacket(type, dataTable)`——2 参：`type` string（包类型）、`dataTable` table（数据）。\n- 返回：无。\n- 报错：`handlerName` 非 string 抛类型错误。\n- 底层：`registerEvent(&evPacket, L)`；触发 `firePacketEvent`，数据经 `goToLua` 转表。实时。\n\n**`events.subscribe(packetType, handlerName)`**\n- 作用：**通用数据包订阅**。订阅任意一个数据包类型（按 Go 类型名，如 `\"MovePlayer\"`/`\"SetTime\"`/`\"PlayerList\"`/`\"Text\"`）。订阅后机器人只监听你订阅的包类型，收到就把**完整**数据包广播给该 handler。\n- 参数：`packetType` string 必填（包类型名）；`handlerName` string 必填，回调签名 `onData(dataTable)`——1 参：`dataTable` table（包数据，字段名 snake_case；`[]byte` 给**完整 hex**，不截断）。\n- 返回：无。同插件同类型同 handler 自动去重；重跑上下文跳过注册。\n- 报错：参数非 string 抛类型错误；不在插件上下文调用报错。\n- 底层：`registerPacketSub` → `packetHubSubscribe`（packet_hub.go）。想查有哪些包类型可订阅，可用 AI 的 `list_packets` 工具。清理：插件停止时 `RemovePluginEvents` 一并退订。\n- 示例：\n```lua\nevents.subscribe(\"MovePlayer\", \"onMove\")\nfunction onMove(data)\n  -- data.entity_runtime_id, data.position={x,y,z}, data.yaw ...\n  game.sendChat(\"玩家移动 x=\" .. data.position[1])\nend\n```\n\n**`events.subscribeAll(handlerName)`**\n- 作用：**全量数据包订阅**。订阅**所有**入站数据包（含未知包、未在固定监听列表里的包），收到任意包就广播给该 handler。用于调试协议/服务器行为、观察未知包。\n- 参数：`handlerName` string 必填，回调签名 `onData(dataTable)`——1 参：`dataTable` table，字段：`seq`（序号）、`at`（时间 HH:MM:SS.mmm）、`direction`（恒为 \"inbound\"）、`bot`（\"BotIndex:display\"）、`packet_type`（Go 类型名，未知包为 \"Unknown\"）、`packet_id`（协议 ID）、`fields`（包字段，未知包带 `payload_hex`）、`raw_len`（未知包原始字节数，有则给）。\n- 返回：无。同插件同 handler 自动去重；重跑上下文跳过注册。\n- 报错：参数非 string 抛类型错误；不在插件上下文调用报错。\n- 底层：`registerCaptureSub` → `captureSubscribe`（packet_capture.go，进程级全量捕获 + 历史缓存）。清理：插件停止时 `RemovePluginEvents` 一并退订。\n- 注意：`subscribeAll` 会收到**每个**包（含高频 SetTime/区块包），handler 内务必轻量、快速返回，避免拖慢插件执行队列。数据默认保留最近 60 秒（可让 AI 用 `query_packets` 回看）。\n\n**公共机制**：事件派发是**异步**的（不阻塞收包循环，避免 `onChat` 里 `game.waitMsg/promptChoice` 死锁），每个 handler 串行执行；handler 为 nil 时跳过；执行出错仅记日志，不抛给调用方。\n\n---\n\n### 4.12 http —— 网络请求\n\n`http.*` 返回完整响应对象（含状态码、响应头），非 2xx 也返回 body，不抛异常。默认超时 30 秒，响应体上限 10MB。\n\n**`http.request(method, url, body?, opts?)`**\n- 作用：发送任意 method 的 HTTP 请求，返回完整响应对象。\n- 参数：`method` string 必填；`url` string 必填；`body` string 可选，默认 `\"\"`；`opts` table 可选（含 `headers` 表、`timeout` 秒）。\n- 返回：table。成功 `{ok=true, status=number, body=string, headers=table}`；传输错误 `{ok=false, error=string}`。\n- 报错：无（错误放进 `error` 字段，不抛异常）。\n- 底层：`httpRequestFull(method, u, body, headers, timeout)`。\n\n**`http.get(url, opts?)` / `http.post(url, body?, opts?)` / `http.put(url, body?, opts?)` / `http.delete(url, opts?)`**\n- 作用：对应方法的 HTTP 请求。\n- 参数：同 `request`（get/delete 无 body）。\n- 返回：同 `request` 的响应表。\n- 报错：无（错误进 `error` 字段）。\n- 底层：`pushHTTPResult(L, \"GET/POST/PUT/DELETE\", ...)` → `httpRequestFull`。\n\n**`http.json_encode(v)`**\n- 作用：把 Lua 值转成 JSON 字符串。\n- 参数：`v` 任意 Lua 值。\n- 返回：string。\n- 报错：序列化失败抛 `http.json_encode: <err>`。\n- 底层：同 `game.jsonEncode`——把 Lua 值映射成 JSON 类型后编码成字符串。\n\n**`http.json_decode(s)`**\n- 作用：把 JSON 字符串解析为 Lua 值。\n- 参数：`s` string 必填。\n- 返回：任意 Lua 值。\n- 报错：解析失败抛 `http.json_decode: <err>`。\n- 底层：同 `game.jsonDecode`——把 JSON 解析成对应 Lua 类型（对象→表、数组→1 起索引的表）。\n\n**`http.querify(paramsTable)`**\n- 作用：把参数表编码成 URL query 字符串。\n- 参数：`paramsTable` table 必填（键值都转字符串）。\n- 返回：string，如 `\"a=1&b=2\"`（按键排序，同键累加）。\n- 报错：非 table 抛类型错误。\n- 底层：`url.Values` + `vals.Encode()`。\n\n> 与 `game.httpGet/httpPost` 的区别：`game.*` 返回纯文本、非 200 直接抛错，适合简单场景；`http.*` 返回完整响应对象、携带状态码与响应头、非 2xx 也能拿 body，适合需要细粒度控制的场景。\n\n---\n\n### 4.13 web —— 网页页面\n\n`web.*` 面向局域网把插件暴露成网页。页面/动作注册走 `/web/` 路由（8080 端口）；访问密码可配在插件配置的 `web_password` 字段。页面在插件停止/重载后自动下线。除 `web.emit` 外都是注册类调用，重跑上下文自动跳过。\n\n**`web.page(name, desc?, controls?)`**\n- 作用：声明一个**声明式页面**，在门户 `/web/` 显示卡片，点进由内置模板渲染控件页。\n- 参数：`name` string 必填（插件内唯一，不含 `/ \\ # ? %` 及控制字符）；`desc` string 可选，默认 `\"\"`；`controls` table 可选（控件表，可读字段 `type`=text|button|input|table|switch、`key`、`label`、`action`、`placeholder`、`columns`）。\n- 返回：无。\n- 报错：空名/非法字符/同插件页面名重复注册抛异常。\n- 底层：`registerWebPage(&webPage{Kind:\"declarative\",...})`，写入全局 `webPages` map。\n\n**`web.serve(name, entry?)`**\n- 作用：声明一个**自定义 HTML 页面**，直接服务 `www/` 目录下对应入口文件。\n- 参数：`name` string 必填（规则同 `web.page`）；`entry` string 可选，默认 `\"index.html\"`（相对 `www/`）。\n- 返回：无。\n- 报错：同 `web.page`。\n- 底层：`registerWebPage(&webPage{Kind:\"html\", Entry:entry})`；静态根目录 `插件文件/<id>/www`，经 `webStaticSafe` 防路径逃逸 + `serveWebStatic` 提供。\n\n**`web.action(page, action, handler)`**\n- 作用：绑定一个交互动作——浏览器对 `/web/api/<插件id>/<页面名>` 发请求时，重跑源码并调用 `handler` 处理。\n- 参数：`page` string、`action` string 必填；`handler` **string 必填**（全局**函数名字符串**，不是函数引用）。\n- 返回：无。\n- 报错：缺插件上下文/空名/重复注册抛异常。\n- 底层：`registerWebAction`；执行时新建 LState（2 分钟超时）重跑源码后 `CallByParam` 调 handler，返回值经 `luaToGo` 作为响应 `data` 回传。受独立并发信号量（容量 8）约束。\n\n**`web.emit(page, event, data)`**\n- 作用：把一条事件实时推送给该插件的全部 SSE 客户端。声明式页面内置 JS 按 key 更新控件；自定义页 JS 自行监听。用于后台状态/进度推送。\n- 参数：`page` string 必填（作为 SSE 事件名）；`event` string 必填（会写入数据 map 的 `__event` 键）；`data` 任意 Lua 值必填。\n- 返回：无。\n- 报错：数据无法 JSON 序列化抛 `web.emit: <err>`。\n- 底层：`pushWebEvent(plugin, page, dataJSON)`，构造 SSE 消息写入所有客户端通道（通道满则丢弃，不阻塞 Lua）。**此方法在重跑上下文不跳过**（供 handler 内推送用）。\n\n---\n\n## 五、综合示例：一个简单的管理插件\n\n把上面的 API 串起来，写一个完整示例插件。它做两件事：玩家发 `菜单` 打开菜单（打招呼 / 查余额），并监听玩家进服发欢迎。\n\n```lua\n-- manifest 里 id = \"example\"，pre_plugins = { core_utils = \"1.0.0\" }\n\nlocal core = api.require(\"core_utils\")  -- 跨插件拿货币工具\n\n-- 聊天入口\ngame.registerTrigger({\"菜单\", \"caidan\"}, \"openMenu\")\n\nfunction openMenu(player)\n    local opts = {\"打个招呼\", \"查看我的余额\"}\n    local idx = game.promptChoice(player, \"【示例菜单】请选择\", opts, 20)\n    if idx == 1 then\n        game.sendTargeted(player, \"§a你好，\" .. player .. \"！\")\n    elseif idx == 2 then\n        local bal = core.money_get(player)\n        game.sendTargeted(player, \"§b你的余额: \" .. bal)\n    end\nend\n\n-- 进服欢迎\nfunction onJoin(name)\n    game.sendChat(\"@a\", \"§7[示例] \" .. name .. \" 进入了服务器\")\nend\nevents.onJoin(\"onJoin\")\n```\n\n把它打包成 zip（`manifest.json` + `main.lua`），导入并运行。游戏里发 `菜单` 会出现菜单；每次有玩家进服会收到欢迎消息。\n\n---\n\n## 六、常见模式与最佳实践\n\n### 6.1 数据持久化\n\n插件需要保存的任何数据，都写到 `game.dataDir()` 下的文件里。推荐统一读写模式：\n\n```lua\nlocal function file() return game.dataDir() .. \"/data.json\" end\nlocal function load()\n    local ok, d = pcall(util.json_load, file())\n    if ok and type(d) == \"table\" then return d end\n    return {}\nend\nlocal function save(d)\n    pcall(util.json_write, file(), d)\nend\n```\n\n`pcall` 很重要：文件第一次读取时不存在，`util.json_load` 会抛错，`pcall` 捕获后回退到空表。\n\n### 6.2 菜单的多步交互\n\n`game.promptChoice` 返回 1 起的下标或 `nil`。用处理函数分发到具体分支，每个分支里再嵌套 `promptChoice` 或 `waitMsg` 完成多步输入。\n\n```lua\nfunction mainMenu(player)\n    local idx = game.promptChoice(player, \"主菜单\", {\"子菜单A\", \"直接操作\"}, 20)\n    if idx == 1 then\n        subMenuA(player)   -- 二级菜单\n    elseif idx == 2 then\n        local name = game.waitMsg(player, 15)\n        game.sendTargeted(player, \"你输入了: \" .. tostring(name))\n    end\nend\n```\n\n注意：`promptChoice` 和 `waitMsg` 是阻塞等待，在后台协程里运行，不会卡住机器人主循环；但同一时间一个玩家只能有一个活跃的等待会话。\n\n### 6.3 后台轮询\n\n用 `util.schedule` 做周期任务：\n\n```lua\nfunction onTick()\n    local data = load()\n    for _, pi in ipairs(player.list()) do\n        -- 检查每个在线玩家\n    end\nend\nutil.schedule(2, \"onTick\")\n```\n\n### 6.4 跨插件拆分系统\n\n把大系统拆成\"底层库 + 功能插件\"是推荐做法。底层库（如 `core_utils`）提供无状态纯函数和持久化，用 `plugin_api` 导出；功能插件（领地、商店、防挂）通过 `pre_plugins` 依赖它，用 `api.require` 调用。\n\n### 6.5 错误处理\n\n- 需要\"出错但不中断\"时，用 `pcall` 包住可能抛错的调用。\n- `game.promptChoice` 超时会返回 `nil`，记得判断 `if not idx then return end`。\n- `tonumber` 解析玩家输入时，非数字返回 `nil`，要先判断。\n- 从 `util.json_load` 读到的字段可能是 nil，访问前用 `or 默认值` 兜底。\n\n---\n\n## 七、注意事项与常见坑\n\n**1 起 vs 0 起**：`game.promptChoice` 返回 **1 起** 下标。拿到 `nil` 说明玩家取消或超时。\n\n**保留字**：Lua 关键字（`until`、`end`、`local` 等）不能直接用作表键，除非写成 `[\"until\"]`。\n\n**顶层副作用**：源码会被反复重跑。不要在顶层做\"每次重跑都想执行一次\"的事（开文件、发消息、计数）。放进函数里，或依赖注册机制（已自动去重）。\n\n**状态只在调用内有效**：全局变量每次重跑都重置。跨调用保存状态请用文件。\n\n**系统能力需要授权**：`system.shell` 需要 Shizuku 授权；`system.vibrate`/`system.notify` 不需要。`system.platform()` 在桌面返回 `desktop`，系统能力在桌面不可用。\n\n**指令需要 OP**：`kick`、`give`、`kill`、`gamemode`、`scoreboard` 等指令需要机器人有 OP。无 OP 时不生效但不报错。\n\n**事件延迟**：进服/离服事件靠轮询，有几秒延迟；聊天、数据包事件是实时的。\n\n**执行开销**：触发词、事件、定时、跨插件调用都会重跑源码。对高频路径（如每条聊天都触发 `onChat`）逻辑尽量精简，避免大量文件读写。\n\n**数据目录结构**：一个插件 = `插件文件/<id>/`（代码）+ `插件配置文件/<id>/`（设置）+ `插件数据文件/<id>/`（数据）三处，不要混用。\n\n**网页交互注意**：`web.action` 的 handler 是函数名字符串；页面/动作在插件停止后下线；数据表键若为连续整数 1..n 会被当作数组处理。\n\n---\n\n## 八、写在最后\n\n本文档覆盖了当前插件的全部公开 API，并对每个函数说明了用途、参数、返回值、报错与底层实现。API 仍在演进，若发现某个方法行为与本文不符，或需要本文没有的能力，请反馈，文档会随之更新。\n\n祝开发顺利。\n";

/** Prism 工具箱 · 词库插件开发文档 */
export const PRISM_WORDBANK_DEV_DOC = "# Prism 工具箱 · 词库插件开发文档\n\n词库（wordbank）插件是插件的一种类型（`type = \"wordbank\"`）。它给玩家一份「聊天菜单 → 自动执行」的指令菜单：玩家在游戏里发一个触发词，机器人就按你设计的菜单一步步走——发指令、展开子菜单、或先判断再走不同分支。\n\n词库插件**不需要写代码**，用 Web 界面里**图形化点选**就能搭出来。\n\n---\n\n## 一、词库文件在哪\n\n词库插件在 `插件文件/<id>/` 目录下是一个文件，叫 `<id>词库.json`。它和 Lua 插件一样，也有可选的 `manifest.json`（里面 `type` 写 `wordbank`）和 `docs.md`。\n\n你可以在应用里点「插件管理 → 创建 → 词库插件」，会自动生成空词库并进入编辑界面。\n\n---\n\n## 二、怎么编辑词库（图形化）\n\n打开词库插件后，编辑界面默认是**图形化卡片树**，不用碰 JSON：\n\n- **根菜单**一张大卡片，选项一张张小卡片，子菜单自动缩进嵌套。\n- 点卡片上的「▸」展开/收起，点「编辑」改这张卡片，点「＋子项」在它下面加子选项，点「删除」去掉。\n- 每个选项都能设：**说明**（玩家看到的名字）、**触发词**（玩家发哪个词触发，可多个）、**功能简介**、**仅OP可用**、**参数**（玩家触发时可带的输入）、**动作**（三选一，见下）。\n- 编辑完点「保存」，机器人立即生效。\n\n界面右上还有「源码」页签，能看到/手改生成的 JSON（高级玩家才需要，平时不用碰）。\n\n---\n\n## 三、一个选项的「动作」有三种\n\n| 动作 | 意思 | 例 |\n|------|------|-----|\n| **执行指令** | 触发后发一条或多条游戏指令 | 玩家点「传送」，机器人发 `tp 玩家 0 100 0` |\n| **子菜单** | 再展开一层选项（想套几层都行） | 点「发东西」→ 再给「发钻石/发铁锭」等 |\n| **判断** | 先判断，满足条件走「成功」分支，不满足走「失败」分支；分支里还能再放指令/子菜单/判断 | 「查玩家」→ 玩家是 OP 就执行成功指令，否则提示没权限 |\n\n判断节点还可以填「成功提示」「失败提示」，判断后直接发给玩家一句提示。\n\n---\n\n## 四、判断条件（5 种）\n\n| 条件 | 意思 | 需要填什么 |\n|------|------|-----------|\n| 是否OP | 触发者是不是管理员 | 不用填 |\n| 是否名单内 | 触发者是不是名单里的人（比如服主） | 名单：每行一个玩家名 |\n| 数值范围 | 玩家输入的第几个参数在不在范围内 | 参数序号 + 最小值 + 最大值（可空） |\n| 目标是否在线 | 指定的目标玩家在不在服务器 | 目标（支持 `[玩家名]` `[参数:N]`） |\n| 服务器数值 | 用一条命令查个数字，和设定值比 | 命令 + 操作符(`>`/`>=`/`<`/`<=`/`==`/`!=`) + 比较值 |\n\n例子：「服务器数值」判断积分够不够 —— 命令填 `scoreboard players get [玩家名] 积分`，操作符 `>=`，比较值 `100`。机器人会执行这条命令，取返回结果里的数字和 100 比。\n\n---\n\n## 五、指令占位符\n\n指令里支持两个占位符，执行前替换成真实值：\n\n- `[玩家名]` —— 触发这条指令的玩家。\n- `[参数:N]` —— 玩家带的第 N 个参数（N 从 1 起），按你设的参数顺序对应。\n\n例：玩家发 `发钱 小明 1000`（触发词「发钱」，参数：目标玩家 + 数量），指令 `give [参数:1] diamond [参数:2]` 会变成 `give 小明 diamond 1000`。\n\n玩家没带某个参数时：有默认值用默认值；没有默认值，机器人会在聊天里**问你**，输入「取消」可中止。\n\n---\n\n## 六、游戏里玩家怎么用\n\n1. 玩家发根菜单的触发词（比如「菜单」）。\n2. 机器人发选项列表：`1. 传送  2. 发东西  3. 查玩家`。\n3. 玩家发编号（`1`、`1.`、`1、`都行）**或直接发触发词**（带参数也行）。\n4. 是子菜单就继续列下一层；是指令就执行；是判断就判定后走分支。\n5. 随时发「退出」退出菜单；1 分钟没操作自动关闭。\n\n「仅OP可用」的选项，非 OP 玩家**看不到**也**触发不了**。\n\n---\n\n## 七、旧格式兼容\n\n之前用老格式写的词库（只有「触发词 + 指令」，没有动作/菜单）**不用改，照常能用**——会自动识别为「执行指令」。打开编辑器也会显示成卡片树，可以继续升级。\n\n---\n\n## 八、附录：JSON 结构参考（高级玩家）\n\n图形化界面自动生成的就是这个结构。想手写或从别人那儿拿模板时对照看：\n\n```json\n{\n  \"菜单项\": [\n    {\n      \"说明\": \"指令菜单\",\n      \"触发词\": [\"菜单\"],\n      \"功能简介\": \"主菜单\",\n      \"仅OP可用\": false,\n      \"参数\": [ { \"参数名\": \"数量\", \"类型\": \"int\", \"默认值\": 64 } ],\n      \"动作\": {\n        \"类型\": \"子菜单\",\n        \"子菜单\": [\n          { \"说明\": \"传送\", \"触发词\": [\"传送\"],\n            \"动作\": { \"类型\": \"指令\", \"指令\": [\"tp [玩家名] 0 100 0\"] } },\n          { \"说明\": \"查积分\", \"触发词\": [\"查\"],\n            \"动作\": {\n              \"类型\": \"判断\",\n              \"判断\": {\n                \"条件\": { \"类型\": \"服务器数值\", \"命令\": \"scoreboard players get [玩家名] 积分\", \"操作符\": \">=\", \"比较值\": 100 },\n                \"成功\": { \"类型\": \"指令\", \"指令\": [\"say 达标\"] },\n                \"失败\": { \"类型\": \"指令\", \"指令\": [\"say 积分不够\"] }\n              }\n            } }\n        ]\n      }\n    }\n  ]\n}\n```\n\n- `动作.类型`：`指令` / `子菜单` / `判断` 三种之一。\n- `判断.条件.类型`：`是否OP` / `是否名单内` / `数值范围` / `目标在线` / `服务器数值`。\n- `参数.默认值`：填 `null` 表示必填；填了数字/文字则玩家没带时用它。\n- 需要复杂逻辑（循环、定时、跨插件调用等）时，请用 Lua 插件类型。\n";

/** 各部分的元信息，供 ai_assist_context 的 index 分支使用 */
export const AI_ASSIST_PARTS: { key: string; title: string; chars: number; desc: string }[] = [
  { key: 'capabilities', title: '★ 能力宣言（你有什么能力）', chars: CAPABILITY_MANIFEST.length,
    desc: '连上就该先看这个 —— 你有一整套能力，不是只会发消息' },
  { key: 'prompt', title: 'AI帮写 系统提示词', chars: AI_ASSIST_SYSTEM_PROMPT.length,
    desc: 'AI帮写 的身份设定与工具调用规则，原文' },
  { key: 'tools', title: 'AI帮写 29 个工具', chars: AI_ASSIST_TOOLS_MD.length,
    desc: '内置工具清单（读/写文件、调 Lua、抓包、shell、游戏内调用…）' },
  { key: 'skills', title: '技能知识库（基岩版指令 + FMbe）', chars: SKILL_BEDROCK_COMMANDS.length + SKILL_FMBE_DISPLAY.length,
    desc: '基岩版命令清单/选择器/参数类型 + 狐狸方块实体动画' },
  { key: 'plugin_doc', title: 'Prism 插件开发文档', chars: PRISM_PLUGIN_DEV_DOC.length + PRISM_WORDBANK_DEV_DOC.length,
    desc: '写 / 改 Lua 插件与词库插件必读' },
];

/** 把多个部分拼成一段可直接塞进上下文的大文本 */
export function buildAiAssistContext(part: string): string {
  // ★ 默认返回能力宣言，不是清单。
  //   用户要的是「连上就知道自己有什么能力」，不是「连上先看目录」。
  const p = (part || 'capabilities').toLowerCase();
  if (p === 'capabilities') return CAPABILITY_MANIFEST;
  if (p === 'prompt') return AI_ASSIST_SYSTEM_PROMPT;
  if (p === 'tools') return AI_ASSIST_TOOLS_MD;
  if (p === 'skills') {
    return '===== 技能知识库 · 基岩版指令（bedrock-commands） =====\n\n'
      + SKILL_BEDROCK_COMMANDS
      + '\n\n===== 技能知识库 · FMbe 显示实体（fmbe-display） =====\n\n'
      + SKILL_FMBE_DISPLAY;
  }
  if (p === 'plugin_doc') {
    return '===== Prism 工具箱 · 插件开发文档 =====\n\n' + PRISM_PLUGIN_DEV_DOC
      + '\n\n===== Prism 工具箱 · 词库插件开发文档 =====\n\n' + PRISM_WORDBANK_DEV_DOC;
  }
  if (p === 'all') {
    // 能力宣言排最前 —— 先知道自己能干什么，再看具体知识
    return '===== ★ 能力宣言（你有什么能力） =====\n\n' + CAPABILITY_MANIFEST
      + '\n\n===== AI帮写 系统提示词（原文） =====\n\n' + AI_ASSIST_SYSTEM_PROMPT
      + '\n\n===== AI帮写 29 个内置工具 =====\n\n' + AI_ASSIST_TOOLS_MD
      + '\n\n' + buildAiAssistContext('skills')
      + '\n\n' + buildAiAssistContext('plugin_doc');
  }
  // index
  return AI_ASSIST_PARTS
    .map((x) => `- ${x.key}（${x.chars} 字符）：${x.title} —— ${x.desc}`)
    .join('\n')
    + '\n\n（不传 part 时默认返回 capabilities，即能力宣言）';
}
